window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q10"]=window.__LIBQ["the-gioi-hoan-my"]["q10"]||{};window.__LIBQ["the-gioi-hoan-my"]["q10"]["techniques"]={"updatedAt":"2026-07-24","count":97,"techniques":[{"id":"dai-tran-cam-bay-tren-ba-ngan-duong-da","name":"Đại trận cạm bẫy trên Ba ngàn đường đá","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":["Đả Thần Thạch"],"blurb":"Đại trận kết hợp sát trận, ẩn trận và mê trận để che giấu tượng giả Thạch Hạo và dẫn kẻ truy sát vào cạm bẫy.","detail":"Trận pháp được bố trí quanh tượng giả Thạch Hạo, chỉ để kẻ mang địch ý phát hiện sơ hở rồi bị dẫn dụ hoặc truyền vào tâm trận.","congNang":["Che giấu và dẫn kẻ truy sát vào sát trận"],"nguon":["@c0902"]},{"id":"an-tran-bang-tran-ky-tien-dien","name":"Ẩn trận bằng trận kỳ Tiên điện","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":["Đả Thần Thạch"],"blurb":"Trận pháp dùng trận kỳ mang thủ đoạn Tiên đạo để che giấu tâm trận.","detail":"Đả Thần Thạch dùng trận kỳ Tiên điện làm hạch tâm ẩn trận, khiến cả Thiên Nhãn cũng khó nhìn thấu.","congNang":["Che giấu tâm trận trước Thiên Nhãn"],"nguon":["@c0902"]},{"id":"me-tran-nhieu-lop","name":"Mê trận nhiều lớp","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":["Đả Thần Thạch"],"blurb":"Mê trận được bố trí ở vòng ngoài của cạm bẫy trên Ba ngàn đường đá.","detail":"Nhiều lớp mê trận khiến khu vực cạm bẫy biến mất và dẫn dụ những kẻ cố tìm Thạch Hạo.","congNang":["Dẫn dụ và che giấu"],"nguon":["@c0902"]},{"id":"tran-phap-tuong-gia-tren-ba-ngan-duong-da","name":"Trận pháp tượng giả trên ba ngàn đường đá","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":["Thạch Hạo"],"blurb":"Trận pháp do Thạch Hạo bố trí trên ba ngàn đường đá để dùng tượng giả dụ các cánh quân thảo phạt. Khi khép lưới, nó gần như tiêu diệt toàn bộ lực lượng tiến công.","detail":"Trận pháp khuếch đại tiếng nói, hơi thở và tinh huyết được lưu trong tượng Hoang, khiến đối phương lầm tưởng Thạch Hạo đang bế quan tại đây. Nó phản kích các đợt tấn công, sau đó phát ánh sáng kỳ dị cuốn những người xung quanh vào tuyệt trận.","thuocTinh":"Dụ địch và sát phạt","uyLuc":"Có thể gần như tiêu diệt nhiều cánh quân do các quái thai cổ đại dẫn tới.","dacDiem":"Khuếch đại dấu vết trong tượng giả rồi chuyển khu vực mai phục thành tuyệt trận.","congNang":["Khuếch đại tiếng nói, hơi thở và tinh huyết của Thạch Hạo để tạo giả tượng bế quan.","Cuốn những người vây đánh vào tuyệt trận và sát thương trên diện rộng."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0903","tangDatToi":"Có thể dùng làm bẫy quy mô lớn","trangThai":"Đã bố trí"}],"trangThai":"Đã kích hoạt","capNhatToi":"@c0903","tabs":{"tienTrinh":[{"chuong":"@c0903","loai":"thi triển","importance":"normal","giaiDoan":"Khép lưới","text":"Trận pháp phát ánh sáng kỳ dị, cuốn lực lượng thảo phạt vào tuyệt trận và gần như tiêu diệt toàn bộ các cánh quân.","anchor":"Pháp trận bùng phát, đột nhiền phát ra ánh sáng kỳ dị, chụp xuống tất cả mọi người chung quanh"}]},"nguon":["@c0903"]},{"id":"dao-bang-tuyet-dien-hoa-thai-am","name":"Đạo băng tuyết diễn hóa Thái Âm","cn":"","loai":"cong-phap","loaiLabel":"Đạo pháp","phamCap":"Gần chạm tới cấp độ thành Tiên","hePhai":"Thái Âm","soHuu":["Người mạnh nhất bộ lạc Hàn giới"],"blurb":"Đạo pháp lấy băng tuyết nhập đạo rồi từng bước diễn hóa thành sức mạnh Thái Âm.","detail":"Người mạnh nhất bộ lạc Hàn giới dùng đạo pháp này đóng băng bầu trời và thiên kiếp trong quá trình tiến sát cảnh giới thành Tiên.","thuocTinh":"Băng tuyết và Thái Âm","uyLuc":"Có thể đóng băng thiên địa và thiên kiếp.","dacDiem":"Khởi đầu từ băng tuyết rồi suy diễn tới sức mạnh Thái Âm.","congNang":["Đóng băng thiên địa và thiên kiếp trong lúc độ kiếp."],"nguoiTu":[{"ten":"Người mạnh nhất bộ lạc Hàn giới","tuChuong":"@c0904","tangDatToi":"Gần thành Tiên","trangThai":"Đã tử vong"}],"tabs":{"tienTrinh":[{"chuong":"@c0904","loai":"thi triển","importance":"normal","giaiDoan":"Tiến sát thành Tiên","text":"Người mạnh nhất bộ lạc vận dụng đạo băng tuyết đã diễn hóa thành Thái Âm để đóng băng thiên kiếp.","anchor":"vị kia dùng băng tuyết nhập đạo, từng bước suy diễn hóa thành Thái Âm"}]},"capNhatToi":"@c0904","nguon":["@c0904"]},{"id":"dao-hoa-chu-thien-van-dao","name":"Đạo hỏa chư thiên vạn đạo","cn":"","loai":"bi-thuat","loaiLabel":"Pháp môn tôi luyện","phamCap":"Không rõ","hePhai":"Con đường tu thành tiên khí","soHuu":["Thạch Hạo"],"blurb":"Pháp môn dẫn động lửa của chư thiên vạn đạo để thiêu luyện thân thể và chân ngã.","detail":"Thạch Hạo dẫn lửa từ hư không và bầu trời thiêu đốt bản thân trong ba ngày. Đạo hỏa làm tan băng tuyết cùng quy tắc trên núi và khiến hắn trọng thương, gần như người chết đạo vong.","thuocTinh":"Đạo hỏa","uyLuc":"Có thể thiêu luyện thân thể và chân ngã nhưng cũng khiến người thi triển chịu thương tổn gần như trí mạng.","dacDiem":"Lửa được dẫn động từ hư không và bầu trời, mang theo sức mạnh của nhiều đạo tắc.","congNang":["Thiêu luyện thân thể và chân ngã bằng sức mạnh của chư thiên vạn đạo."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0905","tangDatToi":"Dùng đạo hỏa thiêu thân trong ba ngày","trangThai":"đang tu luyện"}],"capNhatToi":"@c0905","tabs":{"tienTrinh":[{"chuong":"@c0905","loai":"thi triển","importance":"normal","giaiDoan":"Thử luyện tia tiên khí thứ hai","text":"Thạch Hạo dẫn động đạo hỏa thiêu thân trong ba ngày và vượt qua cửa ải với thương thế gần như trí mạng.","anchor":"trên núi tuyết kia xuất hiện từng ngọn lửa"}]},"nguon":["@c0905"]},{"id":"phong-an-ba-muoi-sau-lop-cua-nguyet-thien","name":"Phong ấn ba mươi sáu lớp của Nguyệt Thiền","cn":"","aliases":[],"loai":"bi-thuat","loaiLabel":"Phong ấn","phamCap":"Không rõ","hePhai":"Bổ Thiên giáo","soHuu":["Nguyệt Thiền"],"blurb":"Thủ đoạn phong ấn được Nguyệt Thiền dùng để giam giữ Thạch Hạo tại Hàn giới.","detail":"Phong ấn gồm ba mươi sáu lớp, trói chặt thân thể và trấn phong nguyên thần Thạch Hạo. Nguyệt Thiền gia cố nhiều tầng vì dè chừng tia tiên khí mà hắn đã tu thành.","congNang":["Giam cầm thân thể và trấn phong nguyên thần."],"nguoiTu":[{"ten":"Nguyệt Thiền","tuChuong":"@c0906","tangDatToi":"Thi triển ba mươi sáu lớp","trangThai":"Đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0906","loai":"thi triển","importance":"normal","giaiDoan":"Ba mươi sáu lớp","text":"Nguyệt Thiền hoàn tất ba mươi sáu lớp phong ấn để trấn áp thân thể và nguyên thần Thạch Hạo.","anchor":"Đây là lớp phong ấn thứ ba mươi sáu rồi, ngươi có cần cẩn thận quá như vậy không?"}]},"capNhatToi":"@c0906","nguon":["@c0906"]},{"id":"tan-thu-trong-bao-thuat-tien-hoang","name":"Tán thủ trong bảo thuật Tiên Hoàng","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"Không rõ","hePhai":"Bổ Thiên giáo","soHuu":["Nguyệt Thiền"],"blurb":"Tán thủ thuộc bảo thuật Tiên Hoàng được Nguyệt Thiền thi triển trong động phủ cổ.","detail":"Nguyệt Thiền dùng tán thủ này cưỡng ép dẫn tiên chủng chứa mẫu khí ra khỏi mi tâm Thạch Hạo. Quá trình khiến cả hình thể lẫn nguyên thần của hắn chịu áp lực nghiêm trọng.","congNang":["Dẫn dắt tiên chủng chứa mẫu khí ra khỏi mi tâm."],"nguoiTu":[{"ten":"Nguyệt Thiền","tuChuong":"@c0906","tangDatToi":"Có thể dẫn tiên chủng khỏi mi tâm","trangThai":"Đang tu luyện"}],"tabs":{"tienTrinh":[{"chuong":"@c0906","loai":"thi triển","importance":"normal","giaiDoan":"Dẫn tiên chủng","text":"Nguyệt Thiền thi triển tán thủ để kéo tiên chủng chứa mẫu khí ra khỏi mi tâm Thạch Hạo.","anchor":"Nàng dùng tán thủ trong bảo thuật Tiên Hoàng dẫn dắt \"tiên chủng\" hướng ra ngoài"}]},"capNhatToi":"@c0906","nguon":["@c0906"]},{"id":"nguyen-than-anh-tuong-thuat","name":"Nguyên Thần Ảnh Tượng thuật","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"","soHuu":["Nguyệt Thiền"],"blurb":"Thần thông nguyên thần tạo ảnh tượng có uy lực thật trong thời gian ngắn.","detail":"Nguyệt Thiền dùng thuật này tạo ảnh tượng nguyên thần trong thân thể Thạch Hạo, trong khi nguyên thần chân chính vẫn ở lại chân thân. Trong chương, nàng chỉ có thể miễn cưỡng triển khai một lần.","congNang":["Tạo ảnh tượng nguyên thần có chiến lực thật trong thời gian ngắn."],"dacDiem":"Chỉ có thể miễn cưỡng triển khai một lần.","nguoiTu":[{"ten":"Nguyệt Thiền","tuChuong":"@c0907","tangDatToi":"luyện thành","trangThai":"dang-su-dung"}],"nguon":["@c0907"]},{"id":"bao-thuat-bien-hoa-cua-toc-chu-yem","name":"Bảo thuật biến hóa của tộc Chu Yếm","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"","hePhai":"Tộc Chu Yếm","soHuu":["Lạc Đạo","Lam Nhất Trần","Lộ Dịch"],"blurb":"Bảo thuật được dùng để biến hóa và ẩn náu.","detail":"Thạch Hạo truyền thụ bảo thuật này cho Lạc Đạo, Lam Nhất Trần và Lộ Dịch, giúp họ nhiều lần tránh bị truy sát phát hiện.","congNang":["Biến hóa và ẩn náu"],"nguon":["@c0911"],"tabs":{"tienTrinh":[{"chuong":"@c0911","loai":"xuất hiện","importance":"normal","giaiDoan":"Được truyền thụ để lẩn tránh truy binh","text":"Bảo thuật giúp nhóm Lạc Đạo nhiều lần tránh khỏi truy sát.","anchor":"Nếu không phải Thạch Hạo truyền thụ cho bọn hắn"}]}},{"id":"phu-van-dai-than-thong-kiep-truoc-hac-am-than-tu","name":"Phù văn đại thần thông kiếp trước của Hắc Ám Thần tử","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"","soHuu":["Hắc Ám Thần tử"],"blurb":"Phù văn từ kiếp trước ẩn trong thân thể Hắc Ám Thần tử.","detail":"Đòn đánh xuyên thủng thân thể Tuyết Lâm, khiến vết thương khó khép lại và làm sức chiến đấu của nàng suy giảm mạnh.","uyLuc":"Xuyên thủng thân thể Tuyết Lâm và khiến vết thương khó khép lại.","dacDiem":"Phù văn đại thần thông được ẩn trong thân thể quái vật.","congNang":["Xuyên thủng thân thể đối thủ và gây thương thế nghiêm trọng."],"nguon":["@c0912"]},{"id":"bao-thuat-kim-loai-cua-co-mong","name":"Bảo thuật kim loại của Cổ Mông","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"","hePhai":"","soHuu":["Cổ Mông"],"blurb":"Bảo thuật dùng khí kim loại để dẫn dắt và chuyển hóa lôi đình.","detail":"Cổ Mông nối khí kim loại với Kim Linh giới để chuyển hướng lôi đình và tạo phù văn phản kích, nhưng thế kiểm soát bị phá vỡ.","nguon":["@c0913"],"tabs":{"tienTrinh":[{"chuong":"@c0913","loai":"thi triển","importance":"normal","giaiDoan":"Dẫn dắt lôi đình bằng khí kim loại","text":"Cổ Mông dùng khí kim loại nối với Kim Linh giới để dẫn dắt lôi đình.","anchor":"vô tận khí kim loại hiện lên nối liền Kim Linh giới"}]}},{"id":"kiem-quang-phu-van","name":"Kiếm quang phù văn","cn":"","loai":"kiem-quyet","loaiLabel":"Kiếm thuật","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Kiếm thuật do linh thân Thạch Hạo ngưng tụ bằng phù văn.","detail":"Kiếm quang phù văn được dùng để truy kích Cổ Mông và chém chết hắn.","nguon":["@c0913"],"congNang":["Ngưng tụ kiếm bằng phù văn để truy kích và chém giết đối thủ."],"tabs":{"tienTrinh":[{"chuong":"@c0913","loai":"thi triển","importance":"normal","giaiDoan":"Linh thân dùng kiếm quang truy kích Cổ Mông","text":"Linh thân Thạch Hạo ngưng tụ một thanh kiếm bằng phù văn để truy kích Cổ Mông.","anchor":"một thanh kiếm ánh sáng chói mắt hoàn toàn do phù văn tạo thành"}]}},{"id":"kiem-lo-con-bang","name":"Kiếm lô Côn Bằng","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật diễn hóa","phamCap":"","hePhai":"Côn Bằng","soHuu":["Thạch Hạo"],"blurb":"Kiếm lô Côn Bằng là thuật do Thạch Hạo thi triển bằng cách diễn hóa mười vạn kiếm vũ màu vàng, kết hợp với pháp tắc để dựng thành kiếm lô. Kiếm lô được dùng để phong tỏa Hắc Ám Thần tử bên trong.","detail":"Thạch Hạo vận dụng mười vạn kiếm vũ màu vàng cùng pháp tắc, dựng nên một kiếm lô khổng lồ để giam giữ và phong sát đối thủ. Trong lần thi triển đã biết, Hắc Ám Thần tử bị nhốt bên trong kiếm lô. @c0915","congNang":["Dùng mười vạn kiếm vũ màu vàng kết hợp với pháp tắc dựng thành kiếm lô. @c0915","Phong tỏa và giam giữ đối thủ bên trong kiếm lô. @c0915"],"uyLuc":"Có thể dựng kiếm lô bằng mười vạn kiếm vũ màu vàng và pháp tắc, nhốt Hắc Ám Thần tử bên trong. @c0915","dacDiem":"Mười vạn kiếm vũ màu vàng kết hợp với pháp tắc tạo thành kiếm lô khổng lồ.","trangThai":"dang-co","nguon":["@c0915"],"tabs":{"tienTrinh":[{"chuong":"@c0915","loai":"thi triển","importance":"major","giaiDoan":"Dựng kiếm lô phong tỏa Hắc Ám Thần tử","text":"Thạch Hạo dùng mười vạn kiếm vũ màu vàng và pháp tắc dựng thành kiếm lô nhốt Hắc Ám Thần tử.","anchor":"Mười vạn thanh kiếm khổng lồ, ánh kiếm hóa thành trật tự"}]}},{"id":"kiem-the-luan-hoi-thuong-thuong","name":"Kiếm thể Luân hồi–Thượng thương","cn":"","loai":"bi-thuat","loaiLabel":"Kiếm thuật","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Thạch Hạo ngưng tụ kiếm thể từ phù văn Luân hồi, phù văn Thượng thương và Chí Tôn thuật trời sinh.","detail":"Kiếm thể xuyên thủng những vị trí đã tổn hại theo năm tháng trên thân thể Hắc Ám Thần tử.","congNang":["Phá thân thể và phù văn."],"uyLuc":"Xuyên thủng các điểm yếu trên thân thể dị thường.","dacDiem":"Kết hợp phù văn Luân hồi, Thượng thương và Chí Tôn thuật.","nguon":["@c0915"]},{"id":"dong-thien-duy-nhat-gia-tri-loi-con-bang","name":"Động thiên duy nhất gia trì Lôi–Côn Bằng","cn":"","loai":"than-thong","loaiLabel":"Phòng ngự","phamCap":"","hePhai":"Lôi điện, Côn Bằng","soHuu":["Thạch Hạo"],"blurb":"Thạch Hạo vận chuyển động thiên duy nhất cùng Lôi điện, Côn Bằng và ánh sáng Thượng thương để chống lại Đọa Hồn thuật.","detail":"Động thiên duy nhất bao phủ và tiêu diệt chuông nhỏ đỏ thẫm do Đọa Hồn thuật ngưng tụ.","congNang":["Phòng ngự nguyên thần và pháp tắc."],"dacDiem":"Kết hợp nhiều loại sức mạnh trong động thiên duy nhất.","nguon":["@c0915"]},{"id":"bi-thuat-tam-tang","name":"Bí thuật Tam Táng","cn":"","loai":"bi-thuat","loaiLabel":"Bí thuật","phamCap":"Bí thuật thất truyền","hePhai":"","soHuu":["Hắc Ám Thần tử"],"blurb":"Bí thuật Tam Táng là một pháp môn thất truyền, dựng nên tiểu thế giới đầy mộ cổ và phát ra ba lời táng thiên, táng địa, táng nhân. Hắc Ám Thần tử từng thi triển bí thuật này, nhưng phù văn chưa hoàn chỉnh nên toàn bộ thuật bị Thạch Hạo phá tan. @c0917","detail":"Hắc Ám Thần tử dùng dấu ấn ở mi tâm mở ra một tiểu thế giới mộ cổ, sau đó lần lượt thi triển ba tầng táng thiên, táng địa và táng nhân nhằm mai táng, trấn áp mục tiêu. Người quan chiến nhận định đây là bí thuật thất truyền có uy lực đáng sợ, được đồn có khả năng táng cả Tiên; tuy nhiên, phù văn trong lần thi triển này chưa hoàn chỉnh nên bí thuật không phát huy được toàn bộ sức mạnh và cuối cùng bị Thạch Hạo phá tan. @c0917","thuocTinh":"Mai táng và trấn áp","nguonGoc":"Bí thuật thất truyền","uyLuc":"Bí thuật được đồn có khả năng táng cả Tiên, nhưng lần thi triển của Hắc Ám Thần tử chưa hoàn chỉnh và đã bị Thạch Hạo phá tan. @c0917","dacDiem":"Triển khai tiểu thế giới mộ cổ bằng dấu ấn ở mi tâm, kết hợp ba lời táng thiên, táng địa và táng nhân; phù văn được thi triển tại @c0917 chưa hoàn chỉnh.","chieuTieuBieu":["Táng Thiên","Táng Địa","Táng Nhân"],"trangThai":"Chưa hoàn chỉnh","congNang":["Dựng tiểu thế giới mộ cổ để mai táng và trấn áp mục tiêu thông qua ba tầng táng thiên, táng địa, táng nhân. @c0917"],"nguoiTu":[{"ten":"Hắc Ám Thần tử","tuChuong":"@c0917","tangDatToi":"Phù văn chưa hoàn chỉnh","trangThai":"Đã thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c0917","loai":"thi triển","importance":"major","giaiDoan":"Phù văn chưa hoàn chỉnh","text":"Hắc Ám Thần tử thi triển ba lời táng thiên, địa, nhân trong tiểu thế giới mộ cổ, nhưng toàn bộ thuật bị Chí Tôn thuật của Thạch Hạo phá tan.","anchor":"Táng Thiên, táng Địa, táng Nhân"}]},"capNhatToi":"@c0917","nguon":["@c0917"]},{"id":"dai-tran-phong-toa-chien-truong","name":"Đại trận phong tỏa chiến trường","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":["Quân Đạo"],"blurb":"Trận pháp do Quân Đạo bố trí bằng trận đài và pháp kỳ để phong tỏa toàn bộ chiến trường. Nó bị Đả Thần Thạch làm suy yếu rồi bị hủy khi hư không chấn động.","detail":"Quân Đạo bí mật đặt trận đài và pháp kỳ quanh chiến trường trước khi kích hoạt vòng phong tỏa nhằm vây kín Thạch Hạo. Đả Thần Thạch dùng hào quang chống lại trận kỳ, làm hiệu lực suy giảm, sau đó toàn bộ đại trận bị phá hủy trong biến động hư không.","dacDiem":"Dùng nhiều cờ lớn bao phủ bốn phía và phong tỏa chiến trường.","congNang":["Phong tỏa khu vực giao chiến và hạn chế mục tiêu thoát khỏi vòng vây."],"nguoiTu":[{"ten":"Quân Đạo","tuChuong":"@c0917","tangDatToi":"Hoàn tất bố trí","trangThai":"Trận pháp đã bị hủy"}],"trangThai":"Đã bị hủy","tabs":{"tienTrinh":[{"chuong":"@c0917","loai":"thi triển","importance":"normal","giaiDoan":"Hoàn thành rồi bị phá hủy","text":"Quân Đạo kích hoạt trận đài và pháp kỳ để phong tỏa chiến trường, nhưng trận thế bị Đả Thần Thạch làm suy yếu rồi sụp đổ trong biến động hư không.","anchor":"từng cây cờ lớn bao phủ khắp bốn phía"}]},"capNhatToi":"@c0917","nguon":["@c0917"]},{"id":"hu-khong-tram","name":"Hư Không trảm","cn":"","loai":"than-thong","loaiLabel":"Sát chiêu không gian","phamCap":"","hePhai":"Không gian","soHuu":["Liệp Sát giả của Thiên quốc","Thạch Hạo"],"blurb":"Hư Không trảm hình thành từ hư không loạn lưu và có thể cắt nát cao thủ.","detail":"Các luồng hư không loạn lưu hình thành lưỡi chém vô hình, gây sát thương nghiêm trọng cho những người tiến vào khu vực nguy hiểm.","congNang":["Hình thành lưỡi chém vô hình từ hư không loạn lưu","Cắt chém hư không"],"uyLuc":"Có thể cắt nát cao thủ.","nguon":["@c0918","@c0919"]},{"id":"phong-toa-thoi-khong-loan-luu","name":"Phong tỏa thời không loạn lưu","cn":"","loai":"khac","loaiLabel":"Bố trí không gian","phamCap":"","hePhai":"Không gian","soHuu":[],"blurb":"Bố trí không gian quanh đảo dược viên ngăn cản người ngoài tiếp cận.","detail":"Phong tỏa mượn sức mạnh do không gian thứ nguyên phun ra. Thạch Hạo và Đả Thần Thạch tìm được điểm yếu để vượt qua.","congNang":["Ngăn cản người ngoài tiếp cận đảo dược viên"],"nguon":["@c0918"]},{"id":"xuc-tran-thuat","name":"Xúc Trận thuật","cn":"","loai":"bi-thuat","loaiLabel":"Bí thuật","phamCap":"","hePhai":"","soHuu":["Đả Thần Thạch"],"blurb":"Thuật dùng để kích hoạt và thăm dò tàn trận.","detail":"Đả Thần Thạch dùng Xúc Trận thuật điều khiển trận kỳ thử phản ứng của tàn trận, từ đó loại bỏ các tuyến đường nguy hiểm và tìm ra lối đi an toàn.","congNang":["Kích hoạt và thăm dò tàn trận"],"nguon":["@c0919"]},{"id":"huyet-dan-tran","name":"Huyết Dẫn trận","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":["Đả Thần Thạch"],"blurb":"Trận pháp dùng huyết dịch để dẫn động và thăm dò.","detail":"Đả Thần Thạch bôi huyết dịch của Tuyết Lâm lên pháp kỳ để bố trí Huyết Dẫn trận kiểm tra phản ứng của Phượng Hoàng sào.","congNang":["Dùng huyết dịch dẫn động và thăm dò"],"nguon":["@c0919"]},{"id":"tran-phap-phong-an-tien-tri","name":"Cấm trận Tiên đạo của dược viên","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Tiên đạo","hePhai":"","soHuu":[],"blurb":"Tàn trận Tiên đạo bảo vệ khu vực dẫn tới Phượng Hoàng sào.","detail":"Cổ trận đã hư hỏng nghiêm trọng nhưng vẫn tạo ra kiếm khí, thần mang, phù văn không gian và sấm chớp đủ sức vây khốn hoặc giết chết người xâm nhập.","congNang":["Tạo lĩnh vực không gian cấm kỵ"],"nguon":["@c0919"]},{"id":"kiem-khi-tien-dao-trong-di-tich","name":"Kiếm khí Tiên đạo trong di tích","cn":"","loai":"khac","loaiLabel":"Kiếm khí","phamCap":"Tiên đạo","hePhai":"Tiên đạo","soHuu":[],"blurb":"Kiếm khí cổ xưa xuất hiện cùng tiên khí trong khu cổ địa của dược đảo.","detail":"Tàn ảnh kiếm khí còn sót lại có thể hủy diệt các tiểu thiên thế giới. Hắc Hâm cho biết kiếm khí ở thời kỳ cực thịnh từng có khả năng chém đứt đại thế giới.","thuocTinh":"Kiếm khí đi kèm tiên khí","uyLuc":"Tàn ảnh hiện tại có thể hủy diệt tiểu thiên thế giới.","dacDiem":"Uy lực còn sót lại đã khiến những người chứng kiến phải run sợ.","congNang":["Đánh trúng và hủy diệt các tiểu thiên thế giới @c0920"],"trangThai":"Còn tàn ảnh trong khu di tích","capNhatToi":"@c0920","tabs":{"tienTrinh":[{"chuong":"@c0920","loai":"xuất hiện","importance":"normal","giaiDoan":"Tàn ảnh kiếm khí","text":"Kiếm khí đi kèm tiên khí xuất hiện trong khu cổ địa và hủy diệt các tiểu thiên thế giới bị nó đánh trúng.","anchor":"kiếm khí ngút trời đi kèm là từng làn tia tiên khí khiến tâm hồn run rẩy"}]},"nguon":["@c0920"]},{"id":"bo-cuc-tran-phap-duoc-vien","name":"Bố cục trận pháp dược viên","cn":"","loai":"khac","loaiLabel":"Khác","phamCap":"","hePhai":"","soHuu":[],"blurb":"Bố cục trận pháp bao quanh dược viên, với các khu vực ẩn chứa huyền cơ và những cửa không gian dẫn tới đường hầm hư không.","detail":"Bạch Quy là người duy nhất thông thạo bố cục trận pháp của hòn đảo, nhờ đó có thể dẫn người đi qua các khu vực ẩn trong dược viên. Trận pháp gắn với những cửa không gian và đường hầm hư không, nhưng Bạch Quy không thể tùy ý điều khiển nó để giết những kẻ khác.","nguon":["@c0922"]},{"id":"nguyen-than-dai-phap","name":"Nguyên thần đại pháp","aliases":[],"loai":"cong-phap","loaiLabel":"Công pháp nguyên thần","phamCap":"","hePhai":"Hệ thống tu luyện Tiên cổ","soHuu":[],"blurb":"Phương pháp chuyên rèn luyện nguyên thần của kỷ nguyên Tiên cổ.","detail":"Nguyên thần đại pháp dùng để rèn luyện nguyên thần và phát động công kích tinh thần trực tiếp.","nguon":["@c0923"],"congNang":["Rèn luyện và công kích bằng nguyên thần."],"nguonGoc":"Kỷ nguyên Tiên cổ","tabs":{"tienTrinh":[{"chuong":"@c0923","loai":"xuất hiện","importance":"normal","giaiDoan":"Phương pháp rèn luyện nguyên thần","text":"Nguyên thần đại pháp được nhắc tới như phương pháp chuyên rèn luyện nguyên thần của kỷ nguyên Tiên cổ.","anchor":"Kỷ nguyên Tiên cổ, hệ thống tu luyện bác đại tinh thâm, đây là phương pháp chuyên rèn luyện nguyên thần"}]}},{"id":"dao-cua-tu-nhien","name":"Đạo của Tự nhiên","cn":"","loai":"khac","loaiLabel":"Đường tu luyện","phamCap":"","hePhai":"","soHuu":["Thái Âm Ngọc Thỏ"],"blurb":"Đạo của Tự nhiên là con đường tu luyện được Thái Âm Ngọc Thỏ sử dụng.","detail":"Con đường này được mô tả là không bá đạo như phương pháp vạn đạo thiêu thân của Thạch Hạo, không buộc người tu phải chịu nguy cơ bị đốt thành tro hoặc tan xương nát thịt.","congNang":["Tu luyện theo tự nhiên, không cần chịu phương thức luyện thể hủy diệt."],"nguon":["@c0924"]},{"id":"phap-mon-dung-the-gioi-thu-lam-tien-chung","name":"Pháp môn dùng Thế Giới thụ làm tiên chủng","cn":"","loai":"cong-phap","loaiLabel":"Pháp môn Tiên đạo","phamCap":"","hePhai":"","soHuu":[],"blurb":"Pháp môn để Thế Giới thụ cắm rễ trong thân thể và diễn sinh đạo tắc.","detail":"Phương thức Tiên đạo này được thiếu nữ áo trắng tiết lộ khi nói về những con đường tu hành của Tiên cổ.","congNang":["Diễn sinh đạo tắc vô tận trong thân thể"],"nguoiTu":[],"tabs":{"tienTrinh":[{"chuong":"@c0926","loai":"hé lộ tầng-chiêu","importance":"normal","giaiDoan":"Được tiết lộ","text":"Thiếu nữ áo trắng kể về phương thức dùng Thế Giới thụ làm tiên chủng và để nó sinh trưởng trong cơ thể.","anchor":"dùng Thế Giới thụ làm tiên chủng, để nó cắm rễ và sinh trưởng trong cơ thể"}]},"nguon":["@c0926"]},{"id":"phap-mon-dung-hop-hat-giong-mo-hinh-vu-tru","name":"Pháp môn dung hợp hạt giống mô hình vũ trụ","cn":"","loai":"cong-phap","loaiLabel":"Pháp môn Tiên đạo","phamCap":"","hePhai":"","soHuu":[],"blurb":"Pháp môn dung hợp hạt giống mô hình vũ trụ với thân thể để sáng tạo vạn vật.","detail":"Đây là một con đường Tiên đạo được nhắc đến trong những truyền thừa huy hoàng của Tiên cổ.","congNang":["Sáng tạo vạn vật trong thân thể"],"nguoiTu":[],"tabs":{"tienTrinh":[{"chuong":"@c0926","loai":"hé lộ tầng-chiêu","importance":"normal","giaiDoan":"Được tiết lộ","text":"Một con đường Tiên đạo kết hợp hạt giống mô hình vũ trụ với thân thể để diễn dịch con đường vô thượng.","anchor":"kết hợp lại với thân thể, sáng tạo nên vạn vật, diễn dịch ra con đường vô thượng"}]},"nguon":["@c0926"]},{"id":"tan-tran-tien-dao-tren-dao-co","name":"Tàn trận Tiên đạo trên đảo cổ","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Tiên cổ","soHuu":[],"blurb":"Tàn trận Tiên đạo còn sót lại trên đảo cổ.","detail":"Bạch Quy ẩn mình trong tàn trận, khiến Đả Thần Thạch không thể tiếp cận và quyết định ở lại chờ cơ hội cổ địa xuyên qua giới bích.","congNang":["Che chở và ngăn người ngoài tiếp cận"],"nguoiTu":[],"tabs":{"tienTrinh":[{"chuong":"@c0926","loai":"xuất hiện","importance":"normal","giaiDoan":"Tàn trận còn sót lại","text":"Bạch Quy ở lại trong tàn trận Tiên đạo để chờ đảo cổ xé rách giới bích.","anchor":"trốn vào trong tàn trận Tiên đạo còn sót lại từ Tiên cổ kia"}]},"nguon":["@c0926"]},{"id":"dao-hoa-luyen-kim-than","name":"Đạo hỏa luyện kim thân","cn":"","loai":"luyen-the","loaiLabel":"Pháp môn luyện thể","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Pháp môn dùng đạo hỏa thiêu luyện thân thể và nguyên thần.","detail":"Thạch Hạo dùng đạo hỏa thiêu đốt kim thân, chân ngã và nguyên thần trong quá trình bế quan.","nguon":["@c0927"]},{"id":"tran-phap-che-giau-chiec-dinh","name":"Trận pháp che giấu chiếc đỉnh","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":["Đả Thần Thạch"],"blurb":"Trận pháp dùng để che giấu chiếc đỉnh đen.","detail":"Đả Thần Thạch bố trí trận pháp che giấu chiếc đỉnh trong dung nham núi lửa.","nguon":["@c0927"]},{"id":"tran-the-nghi-binh","name":"Trận thế nghi binh","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Trận thế dùng để ngụy trang và đánh lạc hướng người truy tìm.","detail":"Thạch Hạo bố trí trận thế giả cùng nhiều hậu chiêu quanh nơi bế quan.","nguon":["@c0927"]},{"id":"quan-sat-tran-bao-ve-dong-phu","name":"Quần sát trận bảo vệ động phủ","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Không rõ","hePhai":"Sát trận","soHuu":["Đả Thần Thạch"],"blurb":"Hệ thống gồm nhiều sát trận liên kết thành tuyệt địa quanh động phủ nơi Thạch Hạo bế quan.","detail":"Đả Thần Thạch bố trí từng tòa sát trận nối liền với nhau để bảo vệ khu vực trung tâm trong dãy núi.","nguonGoc":"Do Đả Thần Thạch bố trí quanh động phủ.","congNang":["Liên kết nhiều sát trận thành tuyệt địa để bảo vệ vùng đất trung tâm @c0928"],"nguoiTu":[{"ten":"Đả Thần Thạch","tuChuong":"@c0928","tangDatToi":"Hoàn thành bố trí quanh động phủ","trangThai":"đang vận hành"}],"trangThai":"đang bảo vệ động phủ","capNhatToi":"@c0928","tabs":{"tienTrinh":[{"chuong":"@c0928","loai":"xuất hiện","importance":"normal","giaiDoan":"Bảo vệ nơi bế quan","text":"Nhiều sát trận do Đả Thần Thạch bố trí liên kết thành tuyệt địa bảo vệ nơi Thạch Hạo tọa quan.","anchor":"từng tòa sát trận kết hợp lại cùng nhau hình thành nên một tuyệt địa, bảo vệ vùng đất ở trung tâm"}]},"nguon":["@c0928"]},{"id":"khuc-goi-hon-cua-co-thanh-tu","name":"Khúc gọi hồn của Cổ Thánh tử","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"Thần miếu","soHuu":["Cổ Thánh tử của Thần miếu"],"blurb":"Pháp môn do Cổ Thánh tử vận dụng để triệu dẫn nguyên thần Thạch Hạo.","detail":"Các ký hiệu được tụng ra, xuyên vào hư không và truyền đến không gian hắc ám, giúp nguyên thần Thạch Hạo nhận biết phương hướng trở về thân thể.","nguon":["@c0930"],"congNang":["Triệu dẫn nguyên thần.","Truyền âm thanh và ký hiệu xuyên qua hư không."],"tabs":{"tienTrinh":[{"chuong":"@c0930","loai":"thi triển","importance":"normal","giaiDoan":"Triệu dẫn nguyên thần Thạch Hạo","text":"Cổ Thánh tử tụng kinh và đưa các ký hiệu vào hư không để tìm nguyên thần Thạch Hạo.","anchor":"Đây tựa như là một khúc gọi hồn, mà cũng như là một khúc ca trấn hồn"}]}},{"id":"than-am-cong-kich-cua-thach-hao","name":"Thần âm công kích của Thạch Hạo","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Thần âm công kích dùng tiếng hét và âm thanh để gây tổn thương.","detail":"Tiếng hét của Thạch Hạo hóa thành sóng khí, làm Quân Đạo thổ huyết và gây tổn thương cho thân thể cùng nguyên thần của những người xung quanh.","congNang":["Công kích thân thể và nguyên thần bằng tiếng hét."],"nguon":["@c0931"]},{"id":"quan-thien-thuat","name":"Quân Thiên thuật","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"","soHuu":["Quân Đạo"],"blurb":"Tuyệt học công thủ của Quân Đạo, tạo ra chùm sáng và sóng khí mạnh.","detail":"Quân Thiên thuật có khả năng công phòng hợp nhất, từng đánh bay nhiều người xung quanh nhưng bị cánh tay quấn tiên khí của Thạch Hạo xuyên phá.","congNang":["Công phòng hợp nhất.","Tạo chùm sáng và sóng khí đánh bay nhiều người xung quanh."],"uyLuc":"Có thể chấn thương nhiều người xung quanh.","nguon":["@c0931"]},{"id":"thien-nhan-cua-cac-vuong-gia-co-dai","name":"Thiên nhãn của các vương giả cổ đại","cn":"","loai":"than-thong","loaiLabel":"Thần thông quan sát","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":["Thập Quan vương","Trích Tiên","Các vương giả cổ đại"],"blurb":"Thần thông quan sát được các vương giả cổ đại hàng đầu vận dụng để nhìn xuyên khí hỗn độn và thấy rõ nguyên thần thần bí.","detail":"Thập Quan vương, Trích Tiên và những vương giả cổ đại mạnh nhất mở thiên nhãn khi nguyên thần hình hài trẻ nhỏ xuất hiện. Thần thông giúp họ nhìn thấy cảnh tượng chân thật bị khí hỗn độn che phủ.","thuocTinh":"Quan sát","uyLuc":"Có thể nhìn rõ nguyên thần thần bí giữa khí hỗn độn.","dacDiem":"Được nhiều vương giả cổ đại đồng thời mở ra để quan sát dị biến quanh Hoàng Kim Đạo cung.","chieuTieuBieu":["Mở thiên nhãn quan sát nguyên thần"],"congNang":["Nhìn rõ nguyên thần thần bí bị khí hỗn độn bao phủ tại @c0934"],"nguoiTu":[{"ten":"Thập Quan vương","tuChuong":"@c0934","tangDatToi":"Không rõ","trangThai":"đang sử dụng"},{"ten":"Trích Tiên","tuChuong":"@c0934","tangDatToi":"Không rõ","trangThai":"đang sử dụng"}],"trangThai":"Đang được sử dụng","capNhatToi":"@c0934","tabs":{"tienTrinh":[{"chuong":"@c0934","loai":"thi triển","importance":"normal","giaiDoan":"Quan sát nguyên thần","text":"Các vương giả cổ đại hàng đầu mở thiên nhãn để nhìn thấy chân tướng của nguyên thần hình hài trẻ nhỏ giữa khí hỗn độn.","anchor":"mấy vị vương giả cổ đại mạnh mẽ nhất mở ra thiên nhãn, nhìn thấy cảnh tượng chân thật"}]},"nguon":["@c0934"]},{"id":"vuc-trang-giam-cam-bon-phuong","name":"Vực tràng giam cầm bốn phương","cn":"","loai":"bi-thuat","loaiLabel":"Vực tràng","phamCap":"Không rõ","hePhai":"Thiên Thần","soHuu":["Thiên Thần chưa lộ danh tính"],"blurb":"Vực tràng do một Thiên Thần chưa lộ danh tính phóng thích để phong tỏa không gian quanh Thạch Hạo.","detail":"Vực tràng khiến hư không vặn vẹo, giam cầm bốn phương và ngăn Thạch Hạo rời khỏi chiến trường. Đây là thủ đoạn trực tiếp xác nhận một Thiên Thần đã khóa chặt và chặn đường hắn.","thuocTinh":"Phong tỏa không gian","uyLuc":"Có thể giam cầm bốn phương quanh Thạch Hạo đang trọng thương.","dacDiem":"Khi được phóng thích, hư không quanh mục tiêu lập tức vặn vẹo và đường lui bị khóa kín.","chieuTieuBieu":["Giam cầm bốn phương"],"congNang":["Giam cầm không gian quanh mục tiêu và ngăn mục tiêu rời đi tại @c0934"],"nguoiTu":[{"ten":"Thiên Thần chưa lộ danh tính","tuChuong":"@c0934","tangDatToi":"Có thể phong tỏa bốn phương","trangThai":"đang sử dụng"}],"trangThai":"Đang được sử dụng","capNhatToi":"@c0934","tabs":{"tienTrinh":[{"chuong":"@c0934","loai":"thi triển","importance":"normal","giaiDoan":"Phong tỏa chiến trường","text":"Thiên Thần chưa lộ danh tính phóng thích vực tràng để phong tỏa không gian quanh Thạch Hạo và ngăn hắn rời đi.","anchor":"có người phóng thích vực tràng, giam cầm bốn phương xung quanh hắn, ngăn cản hắn rời đi"}]},"nguon":["@c0934"]},{"id":"thien-nhan-thong","name":"Thiên Nhãn thông","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Thần thông giúp Thạch Hạo nhìn rõ sự nóng bỏng và tham lam ẩn sâu trong mắt Mã Nguyên.","detail":"Thiên Nhãn thông giúp nhìn thấu cảm xúc và ý đồ ẩn giấu của đối phương.","congNang":["Nhìn thấu cảm xúc và ý đồ ẩn giấu"],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0935","tangDatToi":"","trangThai":"dang-su-dung"}],"tabs":{"tienTrinh":[{"chuong":"@c0935","loai":"thiển triển","importance":"normal","giaiDoan":"Nhìn ra ý đồ đoạt xác của Mã Nguyên","text":"Thạch Hạo vận dụng Thiên Nhãn thông để thấy rõ sự nóng bỏng và tham lam trong mắt Mã Nguyên.","anchor":"hắn nắm giữ Thiên Nhãn thông, có thể thấy rõ ràng sâu trong đáy mắt của Mã Nguyên"}]},"nguon":["@c0935"]},{"id":"trang-vuc-khong-ten-giam-cam-khu-vuc","name":"Tràng vực không tên giam cầm khu vực","cn":"","loai":"khac","loaiLabel":"Tràng vực","phamCap":"","hePhai":"","soHuu":["Mã Nguyên"],"blurb":"Tràng vực phong tỏa không gian quanh chiến trường.","detail":"Tràng vực khiến Thạch Hạo không thể vận dụng Phá Giới phù để thoát khỏi khu vực.","congNang":["Giam cầm khu vực và ngăn Phá Giới phù"],"tabs":{"tienTrinh":[{"chuong":"@c0935","loai":"thi triển","importance":"normal","giaiDoan":"Phong tỏa chiến trường","text":"Tràng vực không tên giam cầm khu vực khiến Thạch Hạo phải trực diện chiến đấu.","anchor":"Khắp nơi này đã bị tràng vực không tên giam cầm nên không cách nào vận dụng được Phá Giới phù"}]},"nguon":["@c0935"]},{"id":"nguyen-rua-nuoc-thien-ha","name":"Nguyền rủa nước thiên hà","cn":"","loai":"bi-thuat","loaiLabel":"Nguyền rủa","phamCap":"Không rõ","hePhai":"Nước thiên hà","soHuu":[],"blurb":"Nguyền rủa nước thiên hà là sức mạnh nguyền rủa đã xâm nhập cơ thể Mã Nguyên và chồng lấp với nguyền rủa Tiên cổ sẵn có. Khi hắn vận dụng đại thần thông, nguyền rủa phản phệ dữ dội, gây thi ban, máu đen và mục ruỗng thân thể.","detail":"Nguyền rủa bắt nguồn từ nước thiên hà, chồng lấp với nguyền rủa Tiên cổ trong cơ thể Mã Nguyên. Mỗi khi Mã Nguyên vận dụng sức mạnh, đặc biệt là đại thần thông, phản phệ càng trở nên nghiêm trọng, khiến thân thể Thiên Thần của hắn bị ăn mòn đến mức phải tự chém bỏ những phần đã nhiễm nguyền rủa. @c0936","thuocTinh":"Nguyền rủa và ăn mòn","uyLuc":"Có thể ăn mòn thân thể Thiên Thần, buộc Mã Nguyên phải tự chém bỏ những phần cơ thể bị nhiễm.","dacDiem":"Phản phệ nghiêm trọng hơn khi nạn nhân vận dụng sức mạnh mạnh hơn.","congNang":["Chồng lấp với nguyền rủa Tiên cổ trong cơ thể nạn nhân. @c0936","Gây phản phệ khi nạn nhân vận dụng sức mạnh, mức độ càng nghiêm trọng nếu dùng sức mạnh càng lớn. @c0936","Gây thi ban, máu đen, ăn mòn và mục ruỗng thân thể Thiên Thần. @c0936"],"trangThai":"Đang phát tác trong cơ thể Mã Nguyên","capNhatToi":"@c0936","tabs":{"tienTrinh":[{"chuong":"@c0936","loai":"xuất hiện","importance":"major","giaiDoan":"Bùng phát trong cơ thể Mã Nguyên","text":"Nguyền rủa từ nước thiên hà chồng lên nguyền rủa Tiên cổ, ăn mòn thân thể Mã Nguyên khi hắn vận dụng đại thần thông.","anchor":"có một sức mạnh yêu tà và đáng sợ đang tàn phá bừa bãi"}]},"nguon":["@c0936"]},{"id":"vuc-trang-phong-toa-cua-ma-nguyen","name":"Vực tràng phong tỏa của Mã Nguyên","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Thiên Thần","hePhai":"Không gian","soHuu":["Mã Nguyên"],"blurb":"Vực tràng do Mã Nguyên dựng lên để giam giữ Thạch Hạo và ngăn cản việc sử dụng Phá Giới phù.","detail":"Vực tràng tạo thành một nhà giam vô hình quanh Thạch Hạo. Khi Mã Nguyên suy yếu vì nguyền rủa, pháp lực duy trì phong tỏa cũng bắt đầu sụp đổ.","thuocTinh":"Phong tỏa không gian","uyLuc":"Có thể giam giữ Thạch Hạo và ngăn Phá Giới phù phát huy tác dụng.","dacDiem":"Hiệu lực phụ thuộc vào trạng thái và pháp lực của Mã Nguyên.","congNang":["Phong tỏa khu vực, hạn chế chạy thoát và ngăn sử dụng Phá Giới phù."],"nguoiTu":[{"ten":"Mã Nguyên","tuChuong":"@c0936","tangDatToi":"Có thể dựng vực tràng giam giữ khu vực","trangThai":"Đang sử dụng"}],"trangThai":"Bắt đầu sụp đổ","capNhatToi":"@c0936","tabs":{"tienTrinh":[{"chuong":"@c0936","loai":"thi triển","importance":"normal","giaiDoan":"Phong tỏa Thạch Hạo","text":"Mã Nguyên duy trì vực tràng để giam Thạch Hạo, nhưng phong tỏa dần sụp đổ khi nguyền rủa khiến hắn suy yếu.","anchor":"Thân thể Thạch Hạo đang ở bên trong một nhà giam vô hình khó có thể chạy thoát hoàn toàn"}]},"nguon":["@c0936"]},{"id":"tran-phap-thien-than-tai-hac-uyen","name":"Trận pháp Thiên Thần tại Hắc uyên","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Thiên Thần","hePhai":"","soHuu":["Thiên Thần Hoàng kim cự tượng tộc","Thiên Thần Long Tước tộc","Thiên Thần Cầu Long tộc"],"blurb":"Trận pháp được bố trí quanh Hắc uyên nhằm mai phục và phong tỏa đường tiến của Thạch Hạo.","detail":"Ba Thiên Thần bố trí trận pháp tại Hắc uyên, khiến Thạch Hạo không thể tiến sâu vào khu vực này sau khi khói đen và nguyền rủa bùng phát.","dacDiem":"Có tác dụng mai phục và phong tỏa khu vực quanh Hắc uyên.","congNang":["Chặn Thạch Hạo tiến vào Hắc uyên."],"capNhatToi":"@c0939","tabs":{"tienTrinh":[{"chuong":"@c0939","loai":"xuất hiện","importance":"normal","giaiDoan":"Phong tỏa Hắc uyên","text":"Trận pháp do ba Thiên Thần bố trí được Thạch Hạo phát hiện khi hắn tìm đường tiến vào Hắc uyên.","anchor":"ở đây hắn phát hiện được trận pháp Thiên Thần do ba người kia bố trí"}]},"nguon":["@c0939"]},{"id":"suc-manh-nguyen-rua-cua-nuoc-thien-ha","name":"Sức mạnh nguyền rủa của nước thiên hà","cn":"","loai":"khac","loaiLabel":"Sức mạnh đặc thù","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Nước thiên hà mang theo tia chớp và sức mạnh nguyền rủa, có thể đánh nát một phần đàn muỗi.","detail":"Thạch Hạo đổ nước thiên hà từ lò luyện đan ra hồ, khiến tia chớp và sức mạnh nguyền rủa lan tràn, giết một phần đàn muỗi nhưng đồng thời thu hút sự chú ý của các muỗi cấp cao.","congNang":["Công kích đàn muỗi bằng tia chớp và nguyền rủa."],"nguon":["@c0941"]},{"id":"co-van-hon-don","name":"Cổ văn hỗn độn","cn":"","loai":"khac","loaiLabel":"Cổ văn dị chủng","phamCap":"Không rõ","hePhai":"","soHuu":[],"blurb":"Hai con cổ văn hỗn độn bám trên đoạn Chân Long cốt dưới đáy hồ.","detail":"Cổ văn hỗn độn từng ăn hơn nửa huyết nhục Chân Long và phát ra gợn sóng cảnh báo khi Thạch Hạo đến gần.","congNang":["Ăn huyết nhục Chân Long"],"nguon":["@c0942"]},{"id":"bi-thuat-thien-than","name":"Bí thuật Thiên Thần","cn":"","loai":"bi-thuat","loaiLabel":"Bí thuật","phamCap":"Thiên Thần","hePhai":"","soHuu":["Mã Nguyên"],"blurb":"Bí thuật dùng uy thế tinh thần để áp chế thần thức đối thủ.","detail":"Mã Nguyên vận dụng bí thuật Thiên Thần, dựa vào uy thế tinh thần mạnh mẽ quét tới nhằm làm thần thức Thạch Hạo bị thương và khiến tâm thần hắn thất thủ, nhưng không đạt kết quả.","congNang":["Áp chế thần thức"],"nguoiTu":[{"ten":"Mã Nguyên","tuChuong":"@c0945","tangDatToi":"","trangThai":"đã thi triển"}],"nguon":["@c0945"]},{"id":"loi-kinh-loi-de-tren-to-giay-vang-kim","name":"Lôi điện thiên kiếp","cn":"","loai":"than-thong","loaiLabel":"Lôi phạt","phamCap":"","hePhai":"","soHuu":[],"blurb":"Thiên kiếp bị cưỡng ép dẫn xuống, xuyên thủng hư không và giáng nguyền rủa lên các Thiên Thần.","detail":"Lôi phạt bao phủ nhiều Thiên Thần, phá hủy hư không và ăn mòn thân thể họ.","nguon":["@c0946"]},{"id":"thien-than-phap-tac","name":"Thiên Thần pháp tắc","cn":"","loai":"than-thong","loaiLabel":"Pháp tắc","phamCap":"","hePhai":"","soHuu":[],"blurb":"Pháp tắc của nhiều Thiên Thần khiến hồ nước đen sôi trào và đàn muỗi phát cuồng.","detail":"Pháp tắc được dùng để công kích hồ nước đen, thiêu khô một phần hồ và kích động sinh linh bên trong.","nguon":["@c0946"]},{"id":"cat-lia-hu-khong","name":"Cắt lìa hư không","cn":"","loai":"than-thong","loaiLabel":"Thần thông không gian","phamCap":"","hePhai":"","soHuu":[],"blurb":"Thần thông liên thủ cắt một mảnh hư không chứa núi sông và mục tiêu.","detail":"Các Thiên Thần phong tỏa không gian, cắt lìa một mảnh hư không rồi đưa Thạch Hạo rời khỏi tiểu thiên thế giới.","nguon":["@c0946"]},{"id":"ao-nghia-luan-hoi","name":"Áo nghĩa Luân hồi","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Áo nghĩa Luân hồi được Thạch Hạo sử dụng để chống trả Đại đạo Trát đao trong thiên kiếp.","detail":"Khi thi triển, áo nghĩa Luân hồi khiến các mảnh vỡ thời gian hiển hóa và quấy nhiễu thời không, hỗ trợ Thạch Hạo vượt qua vết chém của Đại đạo Trát đao.","congNang":["Hiển hóa các mảnh vỡ thời gian.","Quấy nhiễu thời không."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0949","tangDatToi":"","trangThai":"dang-tu"}],"tabs":{"tienTrinh":[{"chuong":"@c0949","loai":"thi triển","importance":"normal","giaiDoan":"Dùng để chống trả Đại đạo Trát đao","text":"Thạch Hạo thi triển áo nghĩa Luân hồi trong cuộc chiến sinh tử với Đại đạo Trát đao.","anchor":"áo nghĩa Luân hồi đều hiển hóa toàn bộ"}]},"nguon":["@c0949"]},{"id":"tien-dao-tan-tran-cua-te-dan-co","name":"Tiên đạo tàn trận của tế đàn cổ","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Tiên đạo tàn trận","hePhai":"Tiên đạo","soHuu":[],"blurb":"Tiên đạo tàn trận tồn tại trên tế đàn cổ ở trung tâm ba ngàn châu từ hơn một kỷ nguyên trước. Trận pháp được tia điện từ vực ngoại kích hoạt, mở ra khả năng dẫn sinh linh không thuộc thế giới hiện tại giáng lâm.","detail":"Đây là một Tiên đạo tàn trận có từ hơn một kỷ nguyên trước, nằm trên tế đàn cổ tại trung tâm ba ngàn châu. Khi tia điện từ vực ngoại đánh thức trận pháp, dấu hiệu xuất hiện cho thấy sinh linh thần bí không thuộc thế giới hiện tại có thể được dẫn tới giáng lâm. @c0953","nguonGoc":"Tồn tại từ hơn một kỷ nguyên trước.","trangThai":"Đã thức tỉnh","capNhatToi":"@c0953","congNang":["Có khả năng dẫn sinh linh không thuộc thế giới hiện tại giáng lâm. @c0953"],"tabs":{"tienTrinh":[{"chuong":"@c0953","loai":"xuất hiện","importance":"major","giaiDoan":"Thức tỉnh","text":"Tia điện từ vực ngoại kích hoạt Tiên đạo tàn trận trên tế đàn cổ, báo hiệu sinh linh thần bí có thể giáng lâm.","anchor":"Tiên đạo tàn trận vân chuyển, có sinh linh thần bí muốn giáng lâm"}]},"nguon":["@c0953"],"dacDiem":"Là Tiên đạo tàn trận cổ xưa trên tế đàn, được kích hoạt bởi tia điện từ vực ngoại. @c0953"},{"id":"phap-tuong-te-linh","name":"Pháp tướng Tế Linh","cn":"","loai":"than-thong","loaiLabel":"Pháp tướng","phamCap":"Không rõ","hePhai":"Tế Linh","soHuu":["Liễu Thần"],"blurb":"Pháp tướng cây Liễu khổng lồ của Liễu Thần hiện ra tại hồ nước trong Tế Linh giới.","detail":"Từ dấu tích vốn chỉ giống một cành cây khô, pháp tướng thức tỉnh thành cây Liễu khổng lồ bao phủ vùng hồ và vươn cao hơn núi.","thuocTinh":"Pháp tướng cây Liễu","trangThai":"Đã thức tỉnh","capNhatToi":"@c0953","nguoiTu":[{"ten":"Liễu Thần","tuChuong":"@c0953","tangDatToi":"Pháp tướng đã hiện ra","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c0953","loai":"xuất hiện","importance":"normal","giaiDoan":"Hiện pháp tướng","text":"Đoạn cây Tế Linh thức tỉnh và hiện thành pháp tướng cây Liễu khổng lồ.","anchor":"đoạn cây của Tế linh lại thức tỉnh và hiện ra pháp tướng"}]},"nguon":["@c0953"]},{"id":"dai-tran-giam-giu-lao-to-hon-toc","name":"Đại trận giam giữ lão tổ Hồn tộc","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Không rõ","hePhai":"Bát Tí Hồn tộc","soHuu":["Bát Tí Hồn tộc"],"blurb":"Đại trận đặt trong vùng núi đá phía sau Hồn đảo, dùng để giam giữ lão tổ Hồn tộc khi phát cuồng và bảo vệ cổ đảo khỏi uy thế của ông.","detail":"Lão tổ Bát Tí Hồn tộc bị những sợi xích lớn cố định giữa đại trận. Khi tiếng rít cấp Giáo chủ vang lên, trận văn trên Hồn đảo phát sáng để ngăn sức mạnh phát tán.","congNang":["Giam giữ lão tổ Bát Tí Hồn tộc và hạn chế sức phá hoại khi ông phát cuồng."],"trangThai":"Đang vận hành","capNhatToi":"@c0955","tabs":{"tienTrinh":[{"chuong":"@c0955","loai":"xuất hiện","importance":"normal","giaiDoan":"Giam giữ lão tổ phát cuồng","text":"Đại trận cùng những sợi xích lớn cố định lão tổ Bát Tí Hồn tộc và ngăn uy thế cấp Giáo chủ phá hủy Hồn đảo.","anchor":"lão ta bị những sợi dây xích to lớn cố định và giam chặt ở giữa đại trận"}]},"nguon":["@c0955"]},{"id":"phap-luc-tran-ap-nguyen-rua-cua-cuong-gia-vuot-thien-than","name":"Pháp lực trấn áp nguyền rủa của cường giả vượt Thiên Thần","cn":"","loai":"bi-thuat","loaiLabel":"Pháp môn trấn áp","phamCap":"Cấp cường giả vượt Thiên Thần","hePhai":"Cường giả bản địa Tiên cổ","soHuu":["Lão tổ Bát Tí Hồn tộc"],"blurb":"Phương thức dùng pháp lực để tự trấn áp nguyền rủa và duy trì sinh mệnh. Biện pháp này không thể ngăn thần trí của người chịu nguyền rủa ngày càng suy thoái.","detail":"Cường giả vượt Thiên Thần cảnh có thể dựa vào pháp lực mạnh mẽ để trấn áp bản thân và tránh chết dưới nguyền rủa. Tuy nhiên, sự ngu dốt và khờ khạo vẫn tăng dần theo thời gian.","thuocTinh":"Trấn áp nguyền rủa","yeuCau":"Cường giả vượt Thiên Thần cảnh","congNang":["Dùng pháp lực tự trấn áp để duy trì sinh mệnh dưới ảnh hưởng của nguyền rủa."],"dacDiem":"Có thể giữ mạng nhưng không ngăn được thần trí ngày càng suy thoái.","nguoiTu":[{"ten":"Lão tổ Bát Tí Hồn tộc","tuChuong":"@c0955","tangDatToi":"Có thể tự trấn áp để duy trì sinh mệnh","trangThai":"Đang chịu nguyền rủa"}],"capNhatToi":"@c0955","tabs":{"tienTrinh":[{"chuong":"@c0955","loai":"xuất hiện","importance":"normal","giaiDoan":"Duy trì sinh mệnh","text":"Pháp lực giúp cường giả vượt Thiên Thần trấn áp bản thân và giữ mạng, nhưng thần trí vẫn ngày càng suy thoái.","anchor":"có thể trấn áp bản thân thế nhưng dù có thể giữ không chết, nhưng vẻ ngu dốt khờ khạo lại từ từ tăng lên"}]},"nguon":["@c0955"]},{"id":"dan-thien-kiep-luyen-than","name":"Dẫn thiên kiếp luyện thân","aliases":[],"loai":"luyen-the","loaiLabel":"Luyện thể","phamCap":"Chân Thần","hePhai":"","soHuu":["Cô Kiếm Vân"],"blurb":"Phương thức dùng thiên kiếp rèn luyện bản thân và đột phá Chân Thần.","detail":"Cô Kiếm Vân dùng một người một kiếm chống lại thiên kiếp, nhờ đó thành công tiến vào lĩnh vực Chân Thần.","nguon":["@c0956"],"nguoiTu":[{"ten":"Cô Kiếm Vân","tuChuong":"@c0956","tangDatToi":"Chân Thần","trangThai":"thanh-cong"}],"congNang":["Rèn luyện bản thân và hỗ trợ đột phá Chân Thần."],"tabs":{"tienTrinh":[{"chuong":"@c0956","loai":"thi triển","importance":"normal","giaiDoan":"Dùng thiên kiếp luyện thân","text":"Cô Kiếm Vân dùng một người một kiếm chống lại thiên kiếp và thành công bước vào lĩnh vực Chân Thần.","anchor":"Một người một chiêu kiếm, hắn chống lại thiên kiếp này."}]}},{"id":"tu-ra-tien-khi","name":"Tu ra tiên khí","cn":"","loai":"khac","loaiLabel":"Cảnh giới","phamCap":"","hePhai":"","soHuu":["Tào Vũ Sinh"],"blurb":"Tào Vũ Sinh đã tu thành một luồng tiên khí để làm nền tảng thử độ kiếp.","detail":"Tào Vũ Sinh đã thành công tu ra một luồng tiên khí nhưng chưa công khai việc này.","nguon":["@c0957"]},{"id":"thien-do","name":"Thiên đồ","cn":"","loai":"khac","loaiLabel":"Bí bảo đạo đồ","phamCap":"","hePhai":"","soHuu":["Ninh Xuyên"],"blurb":"Thiên đồ được Ninh Xuyên gánh theo khi tiến vào biển sấm.","detail":"Ninh Xuyên gánh Thiên đồ tiến vào biển sấm tại di tích Tiên cổ bị nguyền rủa để độ kiếp.","nguon":["@c0957"]},{"id":"dai-tran-co-tai-hung-sao","name":"Đại trận cổ tại Hung sào","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":[],"blurb":"Đại trận cổ còn sót lại tại Hung sào khiến người khác không dám đến gần.","detail":"Đây là di tích trận pháp từ thiên cổ; sự nguy hiểm của nó từng khiến cả Thiên Thần tử vong.","nguon":["@c0957"]},{"id":"phap-cua-lieu-than","name":"Pháp của Liễu Thần","cn":"","loai":"cong-phap","loaiLabel":"Pháp môn sinh mệnh","phamCap":"","hePhai":"Tế Linh","soHuu":["Thạch Hạo"],"blurb":"Pháp môn sinh mệnh do Liễu Thần truyền lại, yêu cầu người tu hành thiêu đốt tinh nguyên bản thân.","detail":"Pháp môn dẫn người tu hành tìm hiểu pháp tắc sinh mệnh bằng cách để tinh nguyên tiêu biến trước. Quá trình này có thể tạo ra sinh mệnh lực mạnh và hỗ trợ khôi phục thương tích nhẹ, nhưng giai đoạn đầu khiến Thạch Hạo khô quắt và suy kiệt.","thuocTinh":"Sinh mệnh","dacDiem":"Phải trải qua quá trình tiêu biến tinh nguyên.","congNang":["Khôi phục thương tích nhẹ","Tăng sinh mệnh lực"],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0959","tangDatToi":"","trangThai":"dang-tu-hanh"}],"tabs":{"tienTrinh":[{"chuong":"@c0959","loai":"thi triển","importance":"normal","giaiDoan":"Thiêu đốt tinh nguyên","text":"Thạch Hạo vận chuyển pháp môn sinh mệnh, khiến tinh huyết và tinh lực nhanh chóng tiêu biến.","anchor":"đây vốn là phương pháp sinh mệnh, vấn Đạo trường sinh"}]},"nguon":["@c0959"]},{"id":"lua-dia-nguc","name":"Lửa địa ngục","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"không rõ","hePhai":"Địa ngục khuyển ba đầu","soHuu":["Địa ngục khuyển ba đầu"],"blurb":"Thần thông phun ra từ đầu bên trái của Địa ngục khuyển ba đầu, có thể thiêu chết thần linh.","detail":"Lửa địa ngục được dùng để thiêu cháy Cổ thụ Thiết Huyết trên võ đài.","congNang":["Thiêu đốt thần linh"],"nguon":["@c0960"]},{"id":"nuoc-hoang-tuyen","name":"Nước hoàng tuyền","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"không rõ","hePhai":"Địa ngục khuyển ba đầu","soHuu":["Địa ngục khuyển ba đầu"],"blurb":"Chất lỏng màu vàng phun ra từ đầu bên phải của Địa ngục khuyển ba đầu.","detail":"Nước hoàng tuyền phối hợp với Lửa địa ngục để công kích Dạ Xoa cánh vàng và có thể hòa tan thần ma.","congNang":["Hòa tan thần ma"],"nguon":["@c0960"]},{"id":"mat-doc-cua-dia-nguc-khuyen","name":"Mắt dọc của Địa ngục khuyển","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"không rõ","hePhai":"Địa ngục khuyển ba đầu","soHuu":["Địa ngục khuyển ba đầu"],"blurb":"Con mắt dọc xuất hiện ở mi tâm của Địa ngục khuyển ba đầu sau khi ba chiếc đầu đồng thời phát sáng.","detail":"Luồng sáng từ mắt dọc xuyên thủng thân thể Dạ Xoa cánh vàng.","congNang":["Xuyên thủng Chân Thần"],"nguon":["@c0960"]},{"id":"thieu-dot-ban-nguyen-sinh-menh","name":"Thiêu đốt bản nguyên sinh mệnh","loai":"bi-thuat","loaiLabel":"Bí thuật","phamCap":"không rõ","hePhai":"không rõ","soHuu":["Thạch Hạo"],"blurb":"Bí pháp Thạch Hạo sử dụng để duy trì chiến lực trong lúc thân thể chịu thương thế nghiêm trọng.","detail":"Thạch Hạo thiêu đốt tinh huyết và tinh nguyên, khiến thần diễm màu vàng bốc cháy bên ngoài cơ thể.","congNang":["Duy trì chiến lực bằng cách tiêu hao bản nguyên"],"nguon":["@c0960"]},{"id":"canh-lieu-mau-vang","name":"Cành liễu màu vàng","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"không rõ","hePhai":"Liễu Thần","soHuu":["Thạch Hạo"],"blurb":"Thạch Hạo hóa phù văn thành một cành liễu màu vàng để xuyên thủng đối thủ.","detail":"Cành liễu màu vàng xuyên thủng thân thể và phá nát nguyên thần Thiểm Điện Tử.","congNang":["Phá hủy thân thể và nguyên thần"],"nguon":["@c0960"]},{"id":"bao-thuat-lieu-than","name":"Bảo thuật Liễu Thần","cn":"","aliases":["Pháp của Liễu Thần","Pháp môn cây khô gặp mùa xuân của Liễu Thần"],"loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"Không rõ","hePhai":"Liễu Thần","soHuu":["Thạch Hạo"],"blurb":"Bảo thuật do Liễu Thần truyền lại, lấy tự diệt rồi tái lập sức sống làm con đường hướng tới trường sinh. Thạch Hạo đã lĩnh hội pháp môn và tiến vào giai đoạn lột xác bằng cách thiêu đốt bản thân. (+) Đại thần thông của Liễu Thần có thể biến hàng vạn lá liễu thành Côn Bằng màu vàng. [CAN-SOAT-GOP] (+) Bảo thuật phóng ra xích thần trật tự màu vàng có sức xuyên phá mạnh. [CAN-SOAT-GOP] (+) Bảo thuật Liễu Thần quy về nguyên thủy khi cây liễu diễn hóa nổ tung thành nguyên thủy tinh khí và tiên thiên hỗn nguyên khí. [CAN-SOAT-GOP]","detail":"Áo nghĩa cốt lõi của Bảo thuật Liễu Thần là đưa người tu đến gần trạng thái mất hết sức sống, sau đó tái lập sinh cơ để hướng tới sức sống phồn thịnh và trường sinh. Pháp môn đòi hỏi duy trì thế cân bằng cực kỳ nguy hiểm trong quá trình tự diệt; nếu thất bại, người tu có thể tọa hóa. Sau khi hiểu rõ pháp môn, Thạch Hạo đã thiêu đốt bản thân để tiến hành lột xác @c0962 @c0963.","thuocTinh":"Sinh cơ, tự diệt và tái lập","nguonGoc":"Liễu Thần","yeuCau":"Người tu phải trải qua trạng thái tự diệt và đứng sát ranh giới tử vong.","uyLuc":"Có khả năng tái lập sức sống sau quá trình tự diệt.","dacDiem":"Muốn hướng tới trường sinh phải trước tiên tự diệt; quá trình này cần giữ thế cân bằng cực kỳ nguy hiểm, thất bại có thể dẫn tới tọa hóa.","trangThai":"Đang được Thạch Hạo tu luyện","capNhatToi":"@c0962","congNang":["Đưa người tu qua trạng thái tự diệt để tái lập sức sống và hướng tới trường sinh @c0962.","Giúp người tu tiến hành lột xác trong lúc thiêu đốt bản thân @c0963."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0962","tangDatToi":"Giai đoạn lột xác kịch liệt","trangThai":"đang lĩnh ngộ"}],"tabs":{"tienTrinh":[{"chuong":"@c0962","loai":"hé lộ tầng-chiêu","importance":"major","giaiDoan":"Áo nghĩa tự diệt và tái lập","text":"Áo nghĩa cốt lõi của bảo thuật được hé lộ là phải tự diệt trước khi tái lập sức sống, nhưng người tu có thể tọa hóa nếu mất cân bằng.","anchor":"muốn trường sinh thì trước phải tự diệt, không phá thì làm sao xây"},{"chuong":"@c0963","loai":"hé lộ tầng-chiêu","importance":"major","giaiDoan":"Lột xác kịch liệt","text":"Thạch Hạo đã hiểu rõ pháp môn và tiến vào giai đoạn lột xác bằng cách thiêu đốt bản thân.","anchor":"pháp của Liễu Thần đã được hắn hiểu rõ và đang trong quá trình lột xác kịch liệt nhất"}]},"nguon":["@c0962","@c0963","@c1014","@c1042","@c1081","@c1134","@c1392"]},{"id":"vo-luong-huyet-kinh","name":"Vô lượng huyết kinh","cn":"","aliases":[],"loai":"bi-thuat","loaiLabel":"Ma công","phamCap":"Không rõ","hePhai":"Huyết đạo","soHuu":["Thanh niên tóc xám tu Vô lượng huyết kinh"],"blurb":"Vô lượng huyết kinh là ma công cho phép người tu phân tán thân thể thành huyết dịch để né tránh công kích, đồng thời tái tạo pháp thân từ phần máu còn sót. Công pháp có khả năng phục sinh quỷ dị nhưng không đem lại bất tử chân chính, bởi người tu chỉ có thêm chín mạng.","detail":"Thanh niên tóc xám từng thi triển Vô lượng huyết kinh trên võ đài, hóa thân thành huyết dịch để tránh đòn và nhiều lần tái tạo pháp thân. Khi giao chiến với Cô Kiếm Vân, hắn liên tục phục sinh sau khi bị áp đảo; tuy nhiên, sau khi chín mạng đều bị tiêu hao, huyết quang cạn sạch và hắn hoàn toàn tử trận. @c0965","thuocTinh":"Huyết dịch và tái sinh","uyLuc":"Có thể tái tạo pháp thân từ một phần huyết dịch còn sót.","dacDiem":"Khả năng phục sinh quỷ dị nhưng bị giới hạn ở chín mạng.","congNang":["Phân tán thân thể thành huyết dịch để né tránh công kích. @c0965","Tái tạo pháp thân từ phần huyết dịch còn sót. @c0965","Đem lại thêm chín mạng cho người tu. @c0965"],"nguoiTu":[{"ten":"Thanh niên tóc xám tu Vô lượng huyết kinh","tuChuong":"@c0965","tangDatToi":"Tu thành","trangThai":"Đã tử trận"}],"trangThai":"Còn truyền thừa","capNhatToi":"@c0965","tabs":{"tienTrinh":[{"chuong":"@c0965","loai":"thi triển","importance":"major","giaiDoan":"Tu thành","text":"Thanh niên tóc xám thi triển Vô lượng huyết kinh để nhiều lần tái tạo pháp thân, nhưng chín mạng cuối cùng đều bị Cô Kiếm Vân tiêu diệt.","anchor":"chỉ cần còn sót lại dù là một giọt thì ta sẽ bất diệt"}]},"nguon":["@c0965"]},{"id":"nhat-nguyen-hoa-hu-khong","name":"Nhất nguyên hóa hư không","cn":"","loai":"than-thong","loaiLabel":"Đại thần thông","phamCap":"Chưa rõ","hePhai":"Ninh Xuyên","soHuu":["Ninh Xuyên"],"blurb":"Đại thần thông giúp Ninh Xuyên hóa thành luồng sáng và di chuyển cực nhanh trên võ đài.","detail":"Ninh Xuyên thi triển pháp này khi đối phó Vô Ảnh đao, hóa thành ánh sáng di chuyển khắp võ đài để tránh lưỡi đao vô hình.","thuocTinh":"Hư không và tốc độ","uyLuc":"Cho phép người thi triển hóa thành ánh sáng và cơ động cực nhanh.","congNang":["Hóa thành luồng sáng và di chuyển cực nhanh để né tránh công kích."],"nguoiTu":[{"ten":"Ninh Xuyên","tuChuong":"@c0966","tangDatToi":"Đã thi triển","trangThai":"đang tu"}],"tabs":{"tienTrinh":[{"chuong":"@c0966","loai":"thi triển","importance":"normal","giaiDoan":"Thi triển trên võ đài","text":"Ninh Xuyên hóa thành luồng sáng để di chuyển khắp võ đài và đối phó Vô Ảnh đao.","anchor":"Nhất nguyên hoá hư không! Ninh Xuyên gào lớn."}]},"capNhatToi":"@c0966","nguon":["@c0966"]},{"id":"dai-than-thong-thien-phuong","name":"Đại thần thông Thiên Phượng","cn":"","aliases":["Thần thông Thiên phượng"],"loai":"than-thong","loaiLabel":"Bảo thuật Thập Hung","phamCap":"Đại thần thông","hePhai":"Bộ tộc Thiên Phượng","soHuu":["Diệp Thiên Vũ"],"blurb":"Đại thần thông của bộ tộc Thiên Phượng được Diệp Thiên Vũ dùng để đối đầu bảo thuật Chân Long.","detail":"Khi thi triển, quanh người Diệp Thiên Vũ xuất hiện thải quang sặc sỡ. Pháp này trực tiếp đối đầu Long quyền của Thập Quan vương trong cuộc chiến giữa hai chí tôn trẻ tuổi.","thuocTinh":"Thiên Phượng","uyLuc":"Có thể đối đầu trực diện với bảo thuật Chân Long hoàn chỉnh.","congNang":["Tạo thải quang sặc sỡ và đối đầu thần thông Chân Long."],"nguoiTu":[{"ten":"Diệp Thiên Vũ","tuChuong":"@c0966","tangDatToi":"Đã thi triển","trangThai":"đang tu"}],"tabs":{"tienTrinh":[{"chuong":"@c0966","loai":"thi triển","importance":"normal","giaiDoan":"Đối đầu bảo thuật Chân Long","text":"Diệp Thiên Vũ thi triển đại thần thông Thiên Phượng để giao chiến với Thập Quan vương.","anchor":"xung quanh hắn sặc sỡ thải quang, đây chính là đại thần thông của bộ tộc Thiên Phượng."}]},"capNhatToi":"@c0966","nguon":["@c0966"]},{"id":"cac-bao-thuat-thap-hung-cua-thap-quan-vuong-va-trich-tien","name":"Các bảo thuật Thập Hung của Thập Quan vương và Trích tiên","cn":"","loai":"khac","loaiLabel":"Hệ bảo thuật","phamCap":"Bảo thuật Thập Hung","hePhai":"Thập Hung","soHuu":["Thập Quan vương","Diệp Thiên Vũ"],"blurb":"Nhóm bảo thuật vô địch thuộc truyền thừa Thập Hung được Thập Quan vương và Diệp Thiên Vũ liên tục thay đổi trong cuộc quyết đấu.","detail":"Trong hơn một trăm hiệp giao chiến, mỗi người vận dụng ba đến bốn loại bảo thuật Thập Hung. Chương chỉ xác nhận rõ bảo thuật Chân Long và đại thần thông Thiên Phượng, chưa nêu tên các pháp còn lại.","dacDiem":"Bao gồm nhiều bảo thuật Thập Hung chưa được nêu đủ tên.","congNang":["Được luân phiên thi triển để công phạt trong cuộc chiến giữa hai chí tôn trẻ tuổi."],"nguoiTu":[{"ten":"Thập Quan vương","tuChuong":"@c0966","tangDatToi":"Thi triển nhiều loại","trangThai":"đang tu"},{"ten":"Diệp Thiên Vũ","tuChuong":"@c0966","tangDatToi":"Thi triển nhiều loại","trangThai":"đang tu"}],"tabs":{"tienTrinh":[{"chuong":"@c0966","loai":"thi triển","importance":"normal","giaiDoan":"Luân phiên nhiều bảo thuật","text":"Thập Quan vương và Diệp Thiên Vũ mỗi người vận dụng ba đến bốn loại bảo thuật Thập Hung trong hơn một trăm hiệp.","anchor":"trong lúc này mỗi bên đều vận dụng tới ba bốn loại bảo thuật vô địch, đều nằm trong Thập Hung cả!"}]},"capNhatToi":"@c0966","nguon":["@c0966"]},{"id":"long-quyen-cua-thap-quan-vuong","name":"Long quyền của Thập Quan vương","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Quyền pháp","phamCap":"Bảo thuật Thập Hung","hePhai":"Chân long","soHuu":["Thập Quan vương"],"blurb":"Quyền pháp của Thập Quan vương, khi thi triển có Chân long quấn quanh cánh tay và làm trời đất biến sắc.","detail":"Thập Quan vương dùng Long quyền trực tiếp công kích Thạch Hạo. Quyền pháp này đối đầu Côn Bằng quyền trong lần giao thủ đầu tiên giữa hai người.","uyLuc":"Có thể chấn động cửu thiên và khiến trời đất biến sắc.","dacDiem":"Chân long quấn quanh cánh tay người thi triển.","congNang":["Công kích trực diện bằng quyền thế mang hình thái Chân long @c0967"],"nguoiTu":[{"ten":"Thập Quan vương","tuChuong":"@c0967","tangDatToi":"","trangThai":"đang sử dụng"}],"capNhatToi":"@c0967","tabs":{"tienTrinh":[{"chuong":"@c0967","loai":"thi triển","importance":"normal","giaiDoan":"Đối chiến Côn Bằng quyền","text":"Thập Quan vương thi triển Long quyền để công kích Thạch Hạo, tạo nên cuộc va chạm trực diện giữa hai Bảo thuật Thập Hung.","anchor":"đây là Long quyền có một không hai"}]},"nguon":["@c0967"]},{"id":"phap-an-chin-co-than","name":"Pháp ấn chín Cổ thần","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Pháp ấn","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":["Ninh Xuyên"],"blurb":"Pháp ấn của Ninh Xuyên có thể triệu hiện chín vị Cổ thần mang khí tức ngập trời.","detail":"Ninh Xuyên kết pháp ấn này để đối kháng quyền vàng của Thạch Hạo. Chín vị Cổ thần xuất hiện bên cạnh hắn và tạo thành thế trấn áp đối thủ.","uyLuc":"Triệu hiện chín vị Cổ thần để trấn áp đối thủ.","dacDiem":"Chín hình bóng Cổ thần đồng thời xuất hiện quanh người thi triển.","congNang":["Triệu hiện chín vị Cổ thần mang khí tức ngập trời @c0967"],"nguoiTu":[{"ten":"Ninh Xuyên","tuChuong":"@c0967","tangDatToi":"","trangThai":"đang sử dụng"}],"capNhatToi":"@c0967","tabs":{"tienTrinh":[{"chuong":"@c0967","loai":"thi triển","importance":"normal","giaiDoan":"Trấn áp Thạch Hạo","text":"Ninh Xuyên kết pháp ấn cường đại, triệu hiện chín vị Cổ thần để đối đầu quyền thế của Thạch Hạo.","anchor":"tiếp đó kết ra một pháp ấn cường đại"}]},"nguon":["@c0967"]},{"id":"than-thong-thien-giac-nghi","name":"Thần thông Thiên Giác Nghĩ","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Thần thông Thập Hung","phamCap":"Thần thông của Thập Hung","hePhai":"Thiên Giác Nghĩ","soHuu":["Diệp Thiên Vũ"],"blurb":"Thần thông Thiên Giác Nghĩ là môn thần thông do Diệp Thiên Vũ đoạt được từ Hung sào, lấy lực lượng thân thể của Thiên Giác Nghĩ làm cốt lõi. Khi được thi triển để đối đầu Thạch Hạ, sức mạnh bộc phát của nó làm rung chuyển võ đài và được mô tả có thể phá nát càn khôn.","detail":"Diệp Thiên Vũ đoạt được thần thông Thiên Giác Nghĩ từ Hung sào và bộc lộ nó trong trận đối đầu với Thạch Hạ. Môn thần thông này tập trung tăng cường sức mạnh thân thể, giúp người thi triển phát huy lực lượng cường đại trong giao chiến trực diện.","thuocTinh":"Sức mạnh thân thể","nguonGoc":"Thiên Giác Nghĩ trong Hung sào","uyLuc":"Sức mạnh bộc phát làm rung chuyển võ đài và được mô tả có thể phá nát càn khôn.","dacDiem":"Lấy lực lượng thân thể của Thiên Giác Nghĩ làm trọng.","congNang":["Tăng cường mạnh mẽ sức mạnh thân thể của người thi triển. @c0968"],"nguoiTu":[{"ten":"Diệp Thiên Vũ","tuChuong":"@c0968","tangDatToi":"Đã thi triển trong giao chiến","trangThai":"đang tu luyện"}],"trangThai":"Đang được Diệp Thiên Vũ sử dụng","capNhatToi":"@c0968","tabs":{"tienTrinh":[{"chuong":"@c0968","loai":"xuất hiện","importance":"major","giaiDoan":"Bộc lộ tại võ đài","text":"Diệp Thiên Vũ bộc lộ thần thông Thiên Giác Nghĩ đoạt được từ Hung sào, dùng sức mạnh thân thể đối đầu Thạch Hạo.","anchor":"Một trong Thập Hung, Thiên Giác Nghĩ, được xưng là sức mạnh đứng hàng đầu"}]},"nguon":["@c0968"]},{"id":"thien-do-troi-sinh-cua-ninh-xuyen","name":"Thiên đồ trời sinh của Ninh Xuyên","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Bảo thuật trời sinh","phamCap":"Không rõ","hePhai":"Bảo thuật trời sinh","soHuu":["Ninh Xuyên"],"blurb":"Pháp đồ trời sinh khắc trên lưng Ninh Xuyên, bên trong hiện ra tinh tú và ngân hà. Nó được dùng để thu giữ và luyện hóa đối thủ.","detail":"Khi mở ra, Thiên đồ hóa thành một thế giới vũ trụ mờ ảo bao phủ mục tiêu. Ninh Xuyên dùng nó trấn áp Thạch Hạo nhưng bị Luân Hồi kiếm mang sức mạnh thời gian đối kháng.","thuocTinh":"Tinh tú và ngân hà","dacDiem":"Pháp đồ khắc trên lưng, chứa hình ảnh vũ trụ tinh tú.","congNang":["Bao phủ, trấn áp và thu đối thủ vào trong pháp đồ để luyện hóa tại @c0968."],"nguoiTu":[{"ten":"Ninh Xuyên","tuChuong":"@c0968","tangDatToi":"Đã thi triển","trangThai":"đang tu luyện"}],"trangThai":"Đang được Ninh Xuyên sử dụng","capNhatToi":"@c0968","tabs":{"tienTrinh":[{"chuong":"@c0968","loai":"thi triển","importance":"normal","giaiDoan":"Trấn áp Thạch Hạo","text":"Ninh Xuyên mở Thiên đồ trời sinh chứa tinh tú và ngân hà nhằm thu luyện Thạch Hạo.","anchor":"sau lưng hắn lao ra một bức Thiên đồ mờ ảo tới khó lường"}]},"nguon":["@c0968"]},{"id":"bao-thuat-troi-sinh-cua-thach-hao","name":"Bảo thuật trời sinh của Thạch Hạo","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Bảo thuật trời sinh","phamCap":"Chưa hoàn thiện","hePhai":"Bảo thuật trời sinh","soHuu":["Thạch Hạo"],"blurb":"Môn thần thông thứ ba của Thạch Hạo, hiện vẫn chưa hoàn thiện. Nó có thể phối hợp với các bảo thuật chí cường để gia tăng uy năng khi giao chiến.","detail":"Thạch Hạo vận dụng môn thần thông này cùng những bảo thuật chí cường để chống lại sức mạnh Thiên Giác Nghĩ do Trích tiên thi triển.","yeuCau":"Phối hợp cùng các bảo thuật chí cường","dacDiem":"Là môn thần thông thứ ba của Thạch Hạo và chưa hoàn thiện.","congNang":["Phối hợp các bảo thuật chí cường để gia tăng uy năng chiến đấu tại @c0968."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0968","tangDatToi":"Chưa hoàn thiện","trangThai":"đang tu luyện"}],"trangThai":"Chưa hoàn thiện","capNhatToi":"@c0968","tabs":{"tienTrinh":[{"chuong":"@c0968","loai":"thi triển","importance":"normal","giaiDoan":"Chống sức mạnh Thiên Giác Nghĩ","text":"Thạch Hạo vận dụng môn thần thông thứ ba chưa hoàn thiện cùng các bảo thuật chí cường để đối đầu Trích tiên.","anchor":"tuy rằng còn chưa hoàn thiện thế nhưng những môn bảo thuật chí cường"}]},"nguon":["@c0968"]},{"id":"thien-cong-cua-quai-thai-toc-vang","name":"Thiên công của quái thai tóc vàng","cn":"","aliases":[],"loai":"cong-phap","loaiLabel":"Công pháp","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":["Quái thai tóc vàng"],"blurb":"Thiên công do một cô gái tóc vàng triển khai trong cuộc hỗn chiến trên võ đài Tiên cổ.","detail":"Khi được triển khai, thiên công khiến cả võ đài rung chuyển dữ dội.","congNang":["Chấn động võ đài khi được triển khai @c0969"],"nguoiTu":[{"ten":"Quái thai tóc vàng","tuChuong":"@c0969","tangDatToi":"","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0969","loai":"thi triển","importance":"normal","giaiDoan":"Thi triển trên võ đài","text":"Quái thai tóc vàng triển khai thiên công, khiến võ đài rung chuyển.","anchor":"thiên công được triển khai khiến nơi đây rung lên ầm ầm"}]},"capNhatToi":"@c0969","nguon":["@c0969"]},{"id":"co-hoa","name":"Cổ hỏa","cn":"","aliases":[],"loai":"khac","loaiLabel":"Nguồn lực Hỏa đạo","phamCap":"Mang khí tức Tiên đạo","hePhai":"Hỏa đạo","soHuu":["Tử Viên Phi"],"blurb":"Cổ hỏa do một vị Chân tiên đã chết để lại và được Tử Viên Phi dung hợp.","detail":"Luồng cổ hỏa này vẫn lưu lại trong cơ thể Tử Viên Phi sau khi hắn đạt thành tựu Thần linh, khác với trường hợp cổ hỏa thường rời khỏi người tu luyện. Khi kết hợp với Đại Phần Thiên Công, nó giúp Tử Viên Phi hóa thành thần tôn Hỏa đạo và phát ra uy năng mang khí tức Tiên đạo.","thuocTinh":"Hỏa đạo","nguonGoc":"Do một vị Chân tiên đã chết để lại.","uyLuc":"Khi dung hợp với Đại Phần Thiên Công, cổ hỏa tạo ra ánh lửa mang khí tức Tiên đạo.","dacDiem":"Vẫn lưu lại trong cơ thể Tử Viên Phi sau khi hắn đạt thành tựu Thần linh.","nguoiTu":[{"ten":"Tử Viên Phi","tuChuong":"@c0970","tangDatToi":"Dung hợp cổ hỏa","trangThai":"đang tu luyện"}],"congNang":["Tăng cường uy năng Hỏa đạo và kết hợp với Đại Phần Thiên Công."],"tabs":{"tienTrinh":[{"chuong":"@c0970","loai":"xuất hiện","importance":"normal","giaiDoan":"Dung hợp với Đại Phần Thiên Công","text":"Tử Viên Phi giữ cổ hỏa của Chân tiên trong cơ thể và dùng nó khi vận chuyển Đại Phần Thiên Công.","anchor":"thế nhưng cổ hỏa của tên này lại lưu lại"}]},"capNhatToi":"@c0970","nguon":["@c0970"]},{"id":"con-duong-phap-tac","name":"Con đường pháp tắc","cn":"","loai":"khac","loaiLabel":"Pháp tắc","phamCap":"","hePhai":"","soHuu":[],"blurb":"Con đường do pháp tắc dựng nên phía sau cánh cửa ánh sáng.","detail":"Những người tiến vào sau Thạch Hạo phải chạy dọc theo con đường này. Họ đã đi hàng vạn dặm mà vẫn chưa nhìn thấy điểm cuối.","dacDiem":"Kéo dài hàng vạn dặm nhưng chưa lộ điểm cuối.","congNang":["Dẫn những người vượt qua cánh cửa ánh sáng tiến sâu vào vùng đất cuối."],"capNhatToi":"@c0971","tabs":{"tienTrinh":[{"chuong":"@c0971","loai":"xuất hiện","importance":"normal","giaiDoan":"Đường vào vùng cuối","text":"Con đường pháp tắc dẫn nhóm thiên tài tiến sâu sau cánh cửa ánh sáng nhưng chưa đưa họ tới điểm cuối.","anchor":"bọn họ lại dọc theo một con đường được xây dựng bằng pháp tắc"}]},"nguon":["@c0971"]},{"id":"luc-hop-thien-cong","name":"Lục Hợp thiên công","cn":"","aliases":[],"loai":"cong-phap","loaiLabel":"Công pháp","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":["Thạch Hạo"],"blurb":"Công pháp được Thạch Hạo vận chuyển khi dốc sức công kích bức tường tuyệt vọng.","detail":"Lục Hợp thiên công phối hợp với ba luồng tiên khí và nhiều bảo thuật trong đòn công kích mạnh nhất của Thạch Hạo, góp phần khiến bức tường mở ra cánh cửa hình người.","congNang":["Gia tăng sức công kích khi phối hợp với những bảo thuật khác."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0972","tangDatToi":"","trangThai":"đang tu luyện"}],"tabs":{"tienTrinh":[{"chuong":"@c0972","loai":"thi triển","importance":"normal","giaiDoan":"Công kích bức tường tuyệt vọng","text":"Thạch Hạo vận chuyển Lục Hợp thiên công cùng nhiều bảo thuật để phát động đòn công kích mạnh nhất vào bức tường.","anchor":"Lục Hợp thiên công chuyển động, tiếng vang ầm ầm ngân lớn"}]},"capNhatToi":"@c0972","nguon":["@c0972"]},{"id":"than-thong-cua-thap-hung","name":"Thần thông của Thập Hung","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Thập Hung","soHuu":["Thạch Hạo"],"blurb":"Những thần thông thuộc truyền thừa của Thập Hung được Thạch Hạo đồng thời khống chế khi chống lại tế đàn.","detail":"Thạch Hạo vận dụng thần thông của Thập Hung cùng Chí Tôn thuật để chống sức ép và lực luyện hóa trong khảo nghiệm tư cách.","congNang":["Chống lại sức ép và lực luyện hóa của tế đàn @c0973"],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0973","tangDatToi":"Có thể đồng thời vận dụng trong khảo nghiệm","trangThai":"đang tu"}],"tabs":{"tienTrinh":[{"chuong":"@c0973","loai":"thi triển","importance":"normal","giaiDoan":"Chống khảo nghiệm tế đàn","text":"Thạch Hạo đồng thời vận dụng thần thông của Thập Hung để chống lại sức luyện hóa.","anchor":"và cũng vận dụng thần thông của Thập Hung đồng thời khống chế"}]},"capNhatToi":"@c0973","nguon":["@c0973"]},{"id":"khao-nghiem-luyen-hoa-cua-te-dan","name":"Khảo nghiệm luyện hóa của tế đàn","cn":"","aliases":[],"loai":"khac","loaiLabel":"Trận pháp khảo nghiệm","phamCap":"Không rõ","hePhai":"Truyền thừa cổ đại","soHuu":[],"blurb":"Khảo nghiệm luyện hóa của tế đàn là cơ chế kiểm nghiệm tư cách được bố trí trong một tế đàn cổ, có thể giam giữ và luyện hóa người lấy hộp ngọc. Khảo nghiệm diễn hóa vật chất cùng sức mạnh pháp tắc như thực thể chân thật, đủ sức uy hiếp cả những nhân vật đã tu thành ba luồng tiên khí và vương giả cổ đại.","detail":"Khi Thạch Hạo lấy hộp ngọc, tế đàn giữ chặt hắn và biến khu vực thành một chiếc đỉnh giam cầm để tiến hành kiểm nghiệm tư cách. Hào quang cùng khí hỗn độn được dùng để ép luyện thân thể, đồng thời nhiều dạng sức mạnh cực hạn công kích cả thể xác lẫn nguyên thần. Những hình thái được diễn hóa gồm thiên lôi, thái dương hỏa, thái âm thủy, gò đất hỗn độn, Thế Giới thạch, kiếm pháp tắc và tiên kim nóng chảy. @c0973","thuocTinh":"Giam cầm, luyện hóa và kiểm nghiệm tư cách","uyLuc":"Có thể đánh nát thân thể người đã tu ra ba luồng tiên khí và đe dọa vương giả cổ đại.","dacDiem":"Diễn hóa vật chất và sức mạnh pháp tắc có hiệu quả tổn thương như thực thể chân thật.","congNang":["Giữ chặt người lấy hộp ngọc, biến khu vực tế đàn thành đỉnh giam cầm và kiểm nghiệm tư cách. @c0973","Dùng hào quang và khí hỗn độn ép luyện thân thể người chịu khảo nghiệm. @c0973","Diễn hóa nhiều loại vật chất và sức mạnh pháp tắc để công kích đồng thời thân thể lẫn nguyên thần. @c0973"],"tabs":{"tienTrinh":[{"chuong":"@c0973","loai":"xuất hiện","importance":"major","giaiDoan":"Phát động khảo nghiệm","text":"Tế đàn giam giữ Thạch Hạo rồi dùng hào quang và khí hỗn độn ép luyện thân thể hắn.","anchor":"Trên tế đàn, những hào quang, những khí hỗn độn đang ép về phía Thạch Hạo"}]},"capNhatToi":"@c0973","nguon":["@c0973"]},{"id":"loi-de-quyen","name":"Lôi Đế quyền","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Quyền pháp","phamCap":"","hePhai":"Lôi Đế","soHuu":["Thạch Hạo"],"blurb":"Quyền pháp mang sức mạnh sấm chớp, được Thạch Hạo phối hợp với Luân Hồi quyền khi giao chiến với Ninh Xuyên.","detail":"Thạch Hạo vận dụng Lôi Đế quyền bằng tay phải, phối hợp cùng Luân Hồi quyền để tạo thế công đan xen sấm chớp và sức mạnh thời gian.","congNang":["Tạo thế công bằng sức mạnh sấm chớp và có thể phối hợp với Luân Hồi quyền."],"uyLuc":"Khi phối hợp với Luân Hồi quyền, quyền pháp tạo nên thế công dữ dội trong trận chiến với Ninh Xuyên.","nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0974","tangDatToi":"","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0974","loai":"thi triển","importance":"normal","giaiDoan":"Phối hợp quyền pháp","text":"Thạch Hạo phối hợp Lôi Đế quyền với Luân Hồi quyền để tấn công Ninh Xuyên.","anchor":"Thạch Hạo trái là Luân Hồi quyền, phải là Lôi Đế quyền"}]},"capNhatToi":"@c0974","nguon":["@c0974"]},{"id":"sau-loai-bao-thuat-cua-ninh-xuyen","name":"Sáu loại bảo thuật của Ninh Xuyên","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"Không rõ","hePhai":"Ninh Xuyên","soHuu":["Ninh Xuyên"],"blurb":"Sáu loại bảo thuật tuyệt thế được Ninh Xuyên diễn hóa từ vòng đeo tay.","detail":"Các bảo thuật hóa thành sáu luồng ráng lành, bao vây và bảo vệ Cô Kiếm Vân để Ninh Xuyên đưa hắn rời khỏi đòn đánh của Thạch Hạo.","thuocTinh":"Bảo vệ và cứu viện","congNang":["Diễn hóa sáu luồng ráng lành để bao vây, bảo vệ và cứu người."],"nguoiTu":[{"ten":"Ninh Xuyên","tuChuong":"@c0975","tangDatToi":"Không rõ","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0975","loai":"thi triển","importance":"normal","giaiDoan":"Sáu bảo thuật cùng hiện","text":"Ninh Xuyên diễn hóa sáu loại bảo thuật để bảo vệ và kéo Cô Kiếm Vân khỏi vùng công kích.","anchor":"diễn biến ra sáu loại bảo thuật tuyệt thế"}]},"capNhatToi":"@c0975","nguon":["@c0975"]},{"id":"bi-thuat-cuon-nguoi-cua-ninh-xuyen","name":"Bí thuật cuốn người","cn":"","aliases":[],"loai":"bi-thuat","loaiLabel":"Bí thuật","phamCap":"Không rõ","hePhai":"Ninh Xuyên","soHuu":["Ninh Xuyên"],"blurb":"Bí thuật được Ninh Xuyên thi triển qua tay áo để cuốn người khác rời đi.","detail":"Ninh Xuyên vung tay áo cuốn Cô Kiếm Vân khỏi vùng nguy hiểm, đồng thời đánh về phía Thạch Hạo để cản trở truy kích.","thuocTinh":"Di chuyển và cứu viện","congNang":["Cuốn và đưa người khác rời khỏi khu vực giao chiến."],"nguoiTu":[{"ten":"Ninh Xuyên","tuChuong":"@c0975","tangDatToi":"Không rõ","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0975","loai":"thi triển","importance":"normal","giaiDoan":"Cuốn người rút lui","text":"Ninh Xuyên dùng tay áo thi triển bí thuật cuốn Cô Kiếm Vân rời đi.","anchor":"tay áo vung lên, hắn vận dụng một bí thuật cuốn lấy"}]},"capNhatToi":"@c0975","nguon":["@c0975"]},{"id":"dai-phap-luc-bao-ve-gioi-bich","name":"Đại pháp lực bảo vệ giới bích","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Giáo chủ","hePhai":"Các Giáo chủ ngoại giới","soHuu":["Các Giáo chủ ngoại giới"],"blurb":"Đại pháp lực của Giáo chủ dùng để bảo vệ người vượt qua giới bích nguy hiểm.","detail":"Nhờ sự bảo hộ của pháp lực này, những người đi sau sáu Thiên Thần có thể vượt giới bích và tiến vào di địa Tiên cổ an toàn.","thuocTinh":"Bảo hộ vượt giới","congNang":["Che chở người vượt qua giới bích nguy hiểm."],"nguoiTu":[{"ten":"Các Giáo chủ ngoại giới","tuChuong":"@c0975","tangDatToi":"Không rõ","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0975","loai":"thi triển","importance":"normal","giaiDoan":"Bảo hộ vượt giới","text":"Các Giáo chủ dùng đại pháp lực bảo vệ những người vượt qua giới bích tiến vào Tiên cổ.","anchor":"chỉ cần Giáo chủ dùng đại pháp lực bảo vệ"}]},"capNhatToi":"@c0975","nguon":["@c0975"]},{"id":"tien-van","name":"Tiên văn","cn":"","aliases":[],"loai":"khac","loaiLabel":"Văn tự tu hành","phamCap":"Văn tự chí cao của Tiên cổ","hePhai":"Tiên cổ","soHuu":[],"blurb":"Loại văn tự hiếm của Tiên cổ được dùng để ghi nội dung trên Đạo thư ngọc thạch.","detail":"Tiên văn khác cốt văn và văn tự thông thường của Tiên cổ, chỉ có rất ít người biết. Thạch Hạo, Cổ tổ Bát Tí Hồn tộc và Lão Thiên Thần Hồn tộc đều không thể đọc loại văn tự này.","thuocTinh":"Văn tự ghi chép truyền thừa","nguonGoc":"Tiên cổ","dacDiem":"Hiếm tới mức ngay cả cường giả cấp Giáo chủ thuộc di dân Tiên cổ cũng không nhận biết được.","trangThai":"Còn tồn tại trên Đạo thư ngọc thạch","capNhatToi":"@c0977","tabs":{"tienTrinh":[{"chuong":"@c0977","loai":"xuất hiện","importance":"normal","giaiDoan":"Được nhận diện trên Đạo thư ngọc thạch","text":"Tiên văn được xác định là loại văn tự chí cao ghi trên Đạo thư ngọc thạch, nhưng cả ba người có mặt đều không thể đọc.","anchor":"đây không phải là văn tự bình thường của Tiên cổ, mà là “Tiên văn” chỉ số ít người biết mà thôi"}]},"nguon":["@c0977"]},{"id":"thanh-te","name":"Thánh tế","cn":"","aliases":[],"loai":"cong-phap","loaiLabel":"Pháp môn tu luyện","phamCap":"Cảnh giới đặc thù giữa Chân Thần và Thiên Thần","hePhai":"Thần đạo","soHuu":["Thạch Hạo"],"blurb":"Thánh tế là con đường tu luyện nguy hiểm nằm giữa Chân Thần và Thiên Thần, nhằm vượt qua giới hạn của Chân Thần. Người thành công có thể mạnh hơn Thiên Thần thông thường và trở thành Vương trong các thần, còn thất bại có thể mất khả năng đột phá hoặc bị hạ cảnh giới.","detail":"Trong quá trình Thánh tế, tu vi dao động dữ dội: khi cao có thể vượt qua Thiên Thần, khi thấp còn thua cả tu sĩ Thần Hỏa cảnh; đồng thời có thể xuất hiện ánh sáng phi tiên, cung điện không tên và con đường cổ thần bí. Vì rủi ro quá lớn, chín phần mười tu sĩ lựa chọn bỏ qua con đường này. Sau khi đạt Chân Thần đại viên mãn, Thạch Hạo bắt đầu Thánh tế bằng cách rút tinh hoa Thánh Nhân mộc để tế luyện bản thân. @c0979","thuocTinh":"Mài giũa đạo và thân thể","yeuCau":"Đạt Chân Thần đại viên mãn trước khi bắt đầu","uyLuc":"Người thành công có thể mạnh hơn Thiên Thần thông thường và được xem là Vương trong các thần.","dacDiem":"Tu vi bất ổn định trong quá trình tu luyện và có thể xuất hiện ánh sáng phi tiên, cung điện không tên cùng con đường cổ thần bí.","congNang":["Tế luyện đạo và thân thể nhằm vượt qua giới hạn của Chân Thần.","Rút tinh hoa Thánh Nhân mộc để tế luyện bản thân sau khi đạt Chân Thần đại viên mãn. @c0979"],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0979","tangDatToi":"Mới bắt đầu","trangThai":"đang tu"}],"trangThai":"Đang được Thạch Hạo tu luyện","capNhatToi":"@c0979","tabs":{"tienTrinh":[{"chuong":"@c0979","loai":"xuất hiện","importance":"major","giaiDoan":"Bắt đầu Thánh tế","text":"Thạch Hạo rút tinh hoa Thánh Nhân mộc tế luyện bản thân sau khi đạt Chân Thần đại viên mãn.","anchor":"chỉ khi bước vào lĩnh vực Thánh tế thì mới có thể tính là Vương bên trong các thần"}]},"nguon":["@c0979"]},{"id":"chan-nhat-vien-co","name":"Chân nhất viễn cố","cn":"","aliases":[],"loai":"cong-phap","loaiLabel":"Pháp tu hành","phamCap":"Không rõ","hePhai":"Pháp của Liễu Thần","soHuu":["Thạch Hạo"],"blurb":"Chân nhất viễn cố là pháp tu hành của Liễu Thần được Thạch Hạo vận dụng trước khi bước vào Thánh tế.","detail":"Thạch Hạo tu hành pháp này trong nửa tháng và đạt Chân Thần đại viên mãn, hoàn tất điều kiện để bắt đầu Thánh tế.","nguonGoc":"Pháp của Liễu Thần","congNang":["Giúp Thạch Hạo hoàn toàn viên mãn Chân Thần cảnh."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0979","tangDatToi":"Viên mãn","trangThai":"đã tu thành giai đoạn được nhắc tới"}],"capNhatToi":"@c0979","tabs":{"tienTrinh":[{"chuong":"@c0979","loai":"có người đại thành","importance":"normal","giaiDoan":"Chân Thần đại viên mãn","text":"Thạch Hạo tu hành Chân nhất viễn cố trong nửa tháng và đạt Chân Thần đại viên mãn.","anchor":"Hắn tu hành pháp của Liễu Thần, chân nhất viễn cố, nửa tháng sau thì hoàn toàn viên mãn"}]},"nguon":["@c0979"]},{"id":"tran-phap-co-dam-lay","name":"Trận pháp cổ đầm lầy","cn":"","aliases":[],"loai":"khac","loaiLabel":"Tàn trận","phamCap":"Tàn trận hơn một kỷ nguyên","hePhai":"Không rõ","soHuu":[],"blurb":"Tàn trận cổ nằm dưới đầm lầy, có thể phát ra gợn sóng khiến sinh linh trong cổ địa rơi vào trạng thái trầm miên.","detail":"Gợn sóng của trận pháp lan khắp cổ địa theo chu kỳ tựa thủy triều, lúc dâng lên rồi lại rút xuống. Nham thạch không chịu ảnh hưởng nên những sinh vật trốn sâu vào hang động có thể tránh được tác động.","nguonGoc":"Tàn trận được lưu lại từ hơn một kỷ nguyên trước","uyLuc":"Có thể khiến mọi sinh linh bị gợn sóng bao phủ rơi vào trạng thái trầm miên tựa như chết.","dacDiem":"Không ảnh hưởng đến nham thạch và vận hành theo chu kỳ dâng rút.","congNang":["Phát gợn sóng khiến sinh linh trầm miên."],"capNhatToi":"@c0979","tabs":{"tienTrinh":[{"chuong":"@c0979","loai":"xuất hiện","importance":"normal","giaiDoan":"Tàn trận kích hoạt","text":"Tàn trận dưới đầm lầy phát gợn sóng trầm miên bao phủ cổ địa và buộc đàn chồn tím phải trốn vào địa quật.","anchor":"là tàn trận được lưu lại hơn một kỷ nguyên trước"}]},"nguon":["@c0979"]},{"id":"tran-phap-ky-tran-kich-no","name":"Trận pháp kỳ trân kích nổ","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Không rõ","hePhai":"Trận đạo","soHuu":["Đả Thần Thạch","Thạch Hạo"],"blurb":"Trận pháp được tạo từ kỳ trân và cài vào lòng đất trong tuyệt địa. Sau một khoảng trì hoãn, nó phát nổ đủ mạnh để đánh thức chồn tím cấp Giáo chủ.","detail":"Đả Thần Thạch bố trí trận pháp theo chỉ dẫn của Thạch Hạo. Trận không nổ ngay khi được kích hoạt mà cần thời gian vận chuyển, nhờ đó Thạch Hạo có thể rời xa trước khi vụ nổ làm kinh động hung thú.","thuocTinh":"Kích nổ trì hoãn","yeuCau":"Dùng kỳ trân bố trí trong lòng đất","congNang":["Tạo vụ nổ mạnh để đánh thức hung thú đang ngủ trong tuyệt địa."],"nguoiTu":[{"ten":"Đả Thần Thạch","tuChuong":"@c0980","tangDatToi":"Có thể bố trí và kích hoạt","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0980","loai":"thi triển","importance":"normal","giaiDoan":"Bố trí trong tuyệt địa","text":"Đả Thần Thạch bố trí trận từ kỳ trân và kích hoạt vụ nổ trì hoãn để đánh thức chồn tím cấp Giáo chủ.","anchor":"Trận pháp bắt đầu vận chuyển thế nhưng cũng không nổ tung ngay lập tức, cần có thời gian nhất định."}]},"capNhatToi":"@c0980","nguon":["@c0980"]},{"id":"bao-thuat-chi-ton-thu-ba","name":"Bảo thuật Chí Tôn thứ ba","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"Không rõ","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Bảo thuật Chí Tôn thứ ba của Thạch Hạo chưa diễn biến trọn vẹn nhưng đã có thể phối hợp với các bảo thuật khác để khuếch đại uy lực.","detail":"Khi Thạch Hạo đánh vào vách đá cuối con đường cổ, bảo thuật này kết hợp cùng những bảo thuật khác, khiến uy lực của đòn đánh tăng lên nhiều lần.","uyLuc":"Khi kết hợp với các bảo thuật khác, uy lực tổng thể có thể tăng lên mấy lần.","nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0982","tangDatToi":"Chưa diễn biến trọn vẹn","trangThai":"đang tu luyện"}],"congNang":["Phối hợp với những bảo thuật khác để tăng uy lực lên mấy lần."],"tabs":{"tienTrinh":[{"chuong":"@c0982","loai":"thi triển","importance":"normal","giaiDoan":"Chưa diễn biến trọn vẹn","text":"Thạch Hạo kết hợp Bảo thuật Chí Tôn thứ ba với các bảo thuật khác khi công kích vách đá cuối con đường cổ.","anchor":"bảo thuật Chí tôn thứ ba tuy rằng còn chưa diễn biến trọn vẹn thế nhưng khi kết hợp cùng với những bảo thuật khác thì có thể làm tăng uy lực lên mấy lần"}]},"capNhatToi":"@c0982","nguon":["@c0982"]},{"id":"lieu-than-phap","name":"Liễu Thần pháp","cn":"","aliases":[],"loai":"cong-phap","loaiLabel":"Công pháp gia trì","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Pháp môn được Thạch Hạo công khai triển khai khi vượt Thần vương kiếp.","detail":"Liễu Thần pháp gia trì thân thể người thi triển, khiến tinh lực cuồn cuộn dâng trào. Thạch Hạo kết hợp pháp môn này với nhiều bảo thuật để liên tiếp vượt qua các tầng lôi kiếp.","thuocTinh":"Gia trì","uyLuc":"Giúp Thạch Hạo duy trì thế tiến công mãnh liệt khi vượt liên tiếp nhiều tầng lôi kiếp.","dacDiem":"Khi triển khai, tinh lực của người sử dụng cuồn cuộn dâng trào.","congNang":["Gia trì bản thân và tăng cường tinh lực cho người thi triển."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0988","tangDatToi":"","trangThai":"đang dùng"}],"trangThai":"đang lưu truyền","capNhatToi":"@c0988","tabs":{"tienTrinh":[{"chuong":"@c0988","loai":"thi triển","importance":"normal","giaiDoan":"Công khai thi triển","text":"Thạch Hạo triển khai Liễu Thần pháp trước quần hùng để gia trì bản thân và tăng cường tinh lực trong Thần vương kiếp.","anchor":"hắn triển khai Liễu Thần pháp ngay trước mặt mọi người để gia trì bản thân, tinh lực cuồn cuộn dâng trào"}]},"nguon":["@c0988"]},{"id":"than-vuong-kiep","name":"Thần vương kiếp","cn":"","aliases":["Thánh nhân kiếp"],"loai":"khac","loaiLabel":"Thiên kiếp","phamCap":"","hePhai":"","soHuu":[],"blurb":"Thần vương kiếp là thiên kiếp đặc thù dùng để khảo nghiệm người bước vào cảnh giới Thánh tế trước khi siêu thoát thành Thần vương. Kiếp nạn gồm nhiều tầng liên tiếp với mức nguy hiểm tăng dần, có lôi đình vượt trên cấp Thiên Thần và tầng thứ chín được cảnh báo là đại kiếp nạn.","detail":"Thần vương kiếp gắn với cảnh giới Thánh tế đầy biến số và bị xem là tử cục đối với người bình thường. Người vượt qua có thể siêu thoát thành Thần vương, còn kẻ thất bại có thể rơi trở lại Thần Hỏa cảnh. Khi kiếp nạn giáng xuống một tiểu thiên thế giới, Thạch Hạo đã liên tiếp vượt qua bảy tầng kiếp nạn @c0988.","thuocTinh":"Lôi kiếp","yeuCau":"Gắn với cảnh giới Thánh tế và được cho là nhằm vào người tu ra ba luồng tiên khí.","uyLuc":"Lôi đình mạnh hơn cấp Thiên Thần, có thể diễn hóa thành sinh linh, binh khí, núi sông và ánh sáng phi tiên.","dacDiem":"Gồm nhiều tầng kiếp nạn liên tiếp, mức độ nguy hiểm tăng dần; tầng thứ chín được cảnh báo là đại kiếp nạn.","congNang":["Khảo nghiệm người bước vào cảnh giới Thánh tế trước khi siêu thoát thành Thần vương.","Khiến người thất bại có thể rơi trở lại Thần Hỏa cảnh."],"trangThai":"đang diễn ra","capNhatToi":"@c0988","tabs":{"tienTrinh":[{"chuong":"@c0988","loai":"xuất hiện","importance":"major","giaiDoan":"Bảy tầng đầu","text":"Thần vương kiếp giáng xuống một tiểu thiên thế giới, nơi Thạch Hạo liên tiếp vượt qua bảy tầng và tiến vào tầng thứ tám.","anchor":"Thánh tế vốn rất kỳ lạ, độ kiếp ở cảnh giới này tự nhiên cũng sẽ có biến số rất lớn, sẽ rất đáng sợ"}]},"nguon":["@c0988"]},{"id":"dai-tran-bao-ve-thach-hao","name":"Đại trận bảo vệ Thạch Hạo","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Không rõ","hePhai":"Bát Tí Hồn tộc và các tộc đồng minh","soHuu":["Bát Tí Hồn tộc","Các tộc đồng minh"],"blurb":"Đại trận được nhiều tộc bản địa Tiên cổ liên thủ dựng lên sau khi lôi kiếp kết thúc để bảo vệ Thạch Hạo.","detail":"Bát Tí Hồn tộc cùng một số tộc khác sử dụng cờ lớn và trận đài bố trí trận pháp quanh Thạch Hạo nhằm ngăn kẻ khác tập kích. Trận được thu lại sau khi hai Giáo chủ hoàn tất việc hóa giải nguyền rủa.","thuocTinh":"Phòng hộ","congNang":["Bảo vệ Thạch Hạo sau lôi kiếp và đề phòng người khác tập kích."],"nguoiTu":[{"ten":"Bát Tí Hồn tộc và các tộc đồng minh","tuChuong":"@c0992","tangDatToi":"","trangThai":"đang sử dụng"}],"trangThai":"Đã thu lại","capNhatToi":"@c0992","tabs":{"tienTrinh":[{"chuong":"@c0992","loai":"xuất hiện","importance":"normal","giaiDoan":"Bố trí bảo vệ","text":"Bát Tí Hồn tộc và các tộc đồng minh dựng đại trận quanh Thạch Hạo sau khi lôi kiếp kết thúc.","anchor":"Đây chính là đại trận là Bát Tí Hồn tộc cùng với một vài tộc khác liên thủ bố trí"}]},"nguon":["@c0992"]},{"id":"tran-phap-bao-ve-ma-nu","name":"Trận pháp bảo vệ Ma nữ","cn":"","aliases":[],"loai":"khac","loaiLabel":"Trận pháp","phamCap":"Chưa rõ","hePhai":"Tiệt Thiên giáo","soHuu":["Ma nữ"],"blurb":"Trận pháp bảo vệ nơi Ma nữ bế quan trong Vạn Vật thổ. Dù phần lớn cấu trúc đã bị phá hủy, tàn lực vẫn có thể phát ra kiếm quang sắc bén.","detail":"Trận pháp vốn có cấu tạo phức tạp nhưng đã bị tổn hại và nóng chảy phần lớn vật liệu. Kiếm quang còn sót lại chém trúng vai Thạch Hạo, cho thấy tàn lực vẫn có sức uy hiếp đáng kể.","thuocTinh":"Phòng ngự và phát kiếm quang","dacDiem":"Đã hư hại, không còn nguyên vẹn nhưng tàn lực vẫn hoạt động.","uyLuc":"Kiếm quang còn sót lại có thể chém bị thương vai Thạch Hạo.","trangThai":"Hư hại","capNhatToi":"@c0996","congNang":["Bảo vệ nơi Ma nữ bế quan và phóng kiếm quang tấn công kẻ xâm nhập."],"tabs":{"tienTrinh":[{"chuong":"@c0996","loai":"xuất hiện","importance":"normal","giaiDoan":"Tàn trận","text":"Trận pháp đã bị tổn hại nghiêm trọng nhưng vẫn phóng kiếm quang chém bị thương vai Thạch Hạo.","anchor":"vốn là trận pháp rất phức tạp nhưng không biết vì nguyên nhân gì lại bị tổn hại"}]},"nguon":["@c0996"]},{"id":"thien-cong-ma-nu-chua-ro-ten","name":"Thiên công Ma nữ tu luyện chưa rõ tên","cn":"","aliases":[],"loai":"cong-phap","loaiLabel":"Thiên công","phamCap":"Chưa rõ","hePhai":"Chưa rõ","soHuu":["Ma nữ"],"blurb":"Môn thiên công chưa rõ tên do chân thân Ma nữ tu luyện. Quá trình tu luyện có sức phá hủy mạnh, khiến trận pháp và phần lớn y phục quanh nàng bị thiêu hủy.","detail":"Ma nữ phải nằm trong Vạn Vật thổ để bảo vệ thân thể khi bế quan tu luyện môn thiên công này. Hiệu quả tu luyện và nguồn gốc của công pháp chưa được tiết lộ.","dacDiem":"Quá trình tu luyện thiêu hủy trận pháp và phần lớn y phục quanh người tu.","trangThai":"Đang tu luyện","capNhatToi":"@c0996","nguoiTu":[{"ten":"Ma nữ","tuChuong":"@c0996","tangDatToi":"Chưa rõ","trangThai":"Đang tu luyện"}],"congNang":["Hiệu quả tu luyện chưa được tiết lộ; quá trình vận công sinh ra sức phá hủy đối với trận pháp và y phục xung quanh."],"tabs":{"tienTrinh":[{"chuong":"@c0996","loai":"xuất hiện","importance":"normal","giaiDoan":"Bế quan trong thần thổ","text":"Ma nữ tiết lộ quá trình tu luyện môn thiên công đã thiêu hủy trận pháp và quần áo, khiến nàng phải nhờ Vạn Vật thổ bảo vệ thân thể.","anchor":"tu luyện môn thiên công kia đã thiêu hủy hết trận pháp và quần áo của ta"}]},"nguon":["@c0996"]},{"id":"than-thong-cai-the-cua-thach-hao","name":"Thần thông cái thế của Thạch Hạo","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":["Thạch Hạo"],"blurb":"Thần thông được Thạch Hạo thi triển khi xông vào thiên kiếp của Ninh Xuyên.","detail":"Thạch Hạo sử dụng thần thông này để đánh thẳng Ninh Xuyên giữa biển sét.","uyLuc":"Đánh thẳng Ninh Xuyên giữa thiên kiếp.","nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c1000","tangDatToi":"","trangThai":"đang tu luyện"}],"tabs":{"tienTrinh":[{"chuong":"@c1000","loai":"thi triển","importance":"normal","giaiDoan":"Giao chiến trong thiên kiếp","text":"Thạch Hạo thi triển thần thông để đánh Ninh Xuyên ngay khi xông vào biển sét.","anchor":"Thạch Hạo vừa mới tới thì liền sử dụng thần thông cái thế đánh giết Ninh Xuyên"}]},"capNhatToi":"@c1000","nguon":["@c1000"]}]};